        '<fillalpha/>'
        '<rect x="0" y="0" w="40" h="10"/>'
        '<fill/>'
        '</foreground>'
        '</shape>'
        '</shapes>',
      );
      expect(includeHost.fill.foregroundTransparency, closeTo(0, 0.05));
      expect(
        hasFillTrans(includeHost, 1),
