  test(
    'mxStencil mxXmlCanvas2D fontbordercolor omitted leftover bakes no label-border plate for LibreOffice',
    () {
      const border = VsdxColor(0xFF1565C0);

      VsdxShape? glyphOf(VsdxShape shape, String text) {
        if ((shape.text ?? '').contains(text)) return shape;
        for (final child in shape.children) {
          final nested = glyphOf(child, text);
          if (nested != null) return nested;
        }
        return null;
      }

      VsdxShape? plateOf(VsdxShape root, int sourceId) {
        final name = '$kLibvisioLabelBorderShapeNamePrefix$sourceId';
        VsdxShape? found;
        void walk(VsdxShape next) {
          if (found != null) return;
          if (next.name == name) {
            found = next;
            return;
          }
          for (final child in next.children) {
            walk(child);
          }
        }

        walk(root);
        return found;
      }

      final omitted = decodeDrawioMxStencilXml(
        '<shape name="O" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<fontbordercolor color="#1565c0"/>'
        '<text str="AB" x="0" y="0" w="40" h="20" align="left" valign="top"/>'
        '<fontbordercolor/>'
        '<text str="CD" x="0" y="30" w="40" h="20" align="left" valign="top"/>'
        '</foreground>'
        '</shape>',
        id: 521,
      );
      expect(glyphOf(omitted, 'AB')!.labelBorderColor, border);
      expect(
        glyphOf(omitted, 'CD')!.labelBorderColor,
        isNull,
        reason: 'omitted color is setFontBorderColor(null)/none; leftover '
            'kept User.veLabelBorderColor so Draw collectLine stroked a '
            'second NoFill plate (`tokens.txt` has no label border)',
      );

      final keep = decodeDrawioMxStencilXml(
        '<shape name="K" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<fontbordercolor color="#1565c0"/>'
        '<text str="AB" x="0" y="0" w="40" h="20" align="left" valign="top"/>'
        '<text str="CD" x="0" y="30" w="40" h="20" align="left" valign="top"/>'
        '</foreground>'
        '</shape>',
      );
      expect(glyphOf(keep, 'AB')!.labelBorderColor, border);
      expect(
        glyphOf(keep, 'CD')!.labelBorderColor,
        border,
        reason: 'without a fontbordercolor node leftover keeps the previous '
            'label border',
      );

      final laterHost = decodeDrawioMxStencilXml(
        '<shape name="L" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<fontbordercolor color="#1565c0"/>'
        '<text str="AB" x="0" y="0" w="40" h="20" align="left" valign="top"/>'
        '<fontbordercolor/>'
        '<text str="CD" x="0" y="30" w="40" h="20" align="left" valign="top"/>'
        '</foreground>'
        '</shape>',
      );
      expect(glyphOf(laterHost, 'AB')!.labelBorderColor, border);
      expect(
        glyphOf(laterHost, 'CD')!.labelBorderColor,
        isNull,
        reason: 'later omitted fontbordercolor leftover-bakes no plate so '
            'Draw does not stroke the second glyph (`tokens.txt` has no '
            'label border)',
      );

      final includeHost = decodeDrawioMxStencilXml(
        '<shapes name="mxgraph.test">'
        '<shape name="host" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<fontbordercolor color="#1565c0"/>'
        '<text str="AB" x="0" y="0" w="40" h="20" align="left" valign="top"/>'
        '<include-shape name="mxgraph.test.tile" x="10" y="10" w="40" h="20"/>'
        '</foreground>'
        '</shape>'
        '<shape name="tile" w="40" h="20" strokewidth="1">'
        '<foreground>'
        '<fontbordercolor/>'
        '<text str="CD" x="0" y="0" w="40" h="20" align="left" valign="top"/>'
        '</foreground>'
        '</shape>'
        '</shapes>',
      );
      expect(glyphOf(includeHost, 'AB')!.labelBorderColor, border);
      expect(
        glyphOf(includeHost, 'CD')!.labelBorderColor,
        isNull,
        reason: 'include-shape shares the canvas; nested omitted '
            'fontbordercolor leftover-bakes no plate',
      );

      final writer = VsdxWriter();
      final parser = DocumentParser();
      var doc = parser.parse(writer.emptyDocument());
      final laterId = doc.pages.first.nextFreeShapeId();
      doc = doc.replacePage(
        0,
        doc.pages.first.addShape(laterHost.copyWith(id: laterId)),
      );
      final leftover = parser
          .parse(
            writer.write(originalBytes: writer.emptyDocument(), edited: doc),
          )
          .pages
          .first
          .findShapeById(laterId)!;
      final leftoverAb = glyphOf(leftover, 'AB')!;
      final leftoverCd = glyphOf(leftover, 'CD')!;
      expect(leftoverAb.labelBorderColor, isNull);
      expect(leftoverCd.labelBorderColor, isNull);
      final plateAb = plateOf(leftover, leftoverAb.id);
      expect(plateAb, isNotNull,
          reason: 'a second save keeps the first NoFill plate Draw paints');
      expect(plateAb!.fill.pattern, 0);
      expect(plateAb.line.pattern, 1);
      expect(plateAb.line.color, border);
      expect(
        plateOf(leftover, leftoverCd.id),
        isNull,
        reason: 'a second save keeps leftover omitted with no second plate',
      );
    },
  );

  test(
    'mxStencil mxXmlCanvas2D translate omitted leftover bakes PinX for LibreOffice',
    () {
      double minMoveX(VsdxShape shape) {
        var min = double.infinity;
        for (final geometry in shape.geometries) {
          for (final command in geometry.commands) {
            if (command is MoveTo) min = math.min(min, command.x);
          }
        }
        return min;
      }

      double minMoveY(VsdxShape shape) {
        var min = double.infinity;
        for (final geometry in shape.geometries) {
          for (final command in geometry.commands) {
            if (command is MoveTo) min = math.min(min, command.y);
          }
        }
        return min;
      }

      double minMoveXDeep(VsdxShape shape) {
        var min = minMoveX(shape);
        for (final child in shape.children) {
          min = math.min(min, minMoveXDeep(child));
        }
        return min;
      }

      const canvasScale = 1.5 / 100;
      final omitted = decodeDrawioMxStencilXml(
        '<shape name="O" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<translate/>'
        '<rect x="0" y="0" w="20" h="10"/>'
        '<fill/>'
        '</foreground>'
        '</shape>',
        id: 522,
      );
      expect(
        minMoveX(omitted),
        closeTo(0, 0.02),
        reason: 'omitted dx/dy is format(null)=NaN; leftover `_number` '
            'snaps to +=0 so Draw collectGeometry does not collapse PinX '
            '(`tokens.txt` PinX)',
      );

      final keep = decodeDrawioMxStencilXml(
        '<shape name="K" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<rect x="0" y="0" w="20" h="10"/>'
        '<fill/>'
        '</foreground>'
        '</shape>',
      );
      expect(
        minMoveX(keep),
        closeTo(0, 0.02),
        reason: 'without a translate node leftover stays unshifted',
      );

      final laterHost = decodeDrawioMxStencilXml(
        '<shape name="L" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<translate dx="30"/>'
        '<rect x="0" y="0" w="20" h="10"/>'
        '<fill/>'
        '<translate/>'
        '<rect x="0" y="20" w="20" h="10"/>'
        '<fill/>'
        '</foreground>'
        '</shape>',
      );
      expect(
        minMoveX(laterHost),
        closeTo(30 * canvasScale, 0.02),
        reason: 'later omitted translate is +=0 so Draw keeps the first '
            'leftover PinX (`tokens.txt` PinX)',
      );
      expect(
        laterHost.children.any(
          (child) => (minMoveX(child) - 30 * canvasScale).abs() < 0.02,
        ),
        isTrue,
        reason: 'later omitted translate leftover-bakes a sibling that '
            'stays on the previous leftover inches',
      );

      final dyHost = decodeDrawioMxStencilXml(
        '<shape name="D" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<translate dx="30"/>'
        '<rect x="0" y="0" w="20" h="10"/>'
        '<fill/>'
        '<translate dy="10"/>'
        '<rect x="0" y="0" w="20" h="10"/>'
        '<fill/>'
        '</foreground>'
        '</shape>',
      );
      expect(minMoveX(dyHost), closeTo(30 * canvasScale, 0.02));
      expect(
        dyHost.children.any(
          (child) =>
              (minMoveX(child) - 30 * canvasScale).abs() < 0.02 &&
              (minMoveY(child) - (minMoveY(dyHost) - 10 * canvasScale)).abs() <
                  0.02,
        ),
        isTrue,
        reason: 'omitted dx on a later dy leftover-bakes a sibling so Draw '
            'keeps previous PinX while applying dy (`tokens.txt` PinX)',
      );

      final includeHost = decodeDrawioMxStencilXml(
        '<shapes name="mxgraph.test">'
        '<shape name="host" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<translate dx="30"/>'
        '<include-shape name="mxgraph.test.tile" x="10" y="10" w="10" h="10"/>'
        '</foreground>'
        '</shape>'
        '<shape name="tile" w="10" h="10" strokewidth="1">'
        '<foreground>'
        '<translate/>'
        '<rect x="0" y="0" w="10" h="10"/>'
        '<fill/>'
        '</foreground>'
        '</shape>'
        '</shapes>',
      );
      expect(
        includeHost.children.any(
          (child) => minMoveXDeep(child) > 35 * canvasScale,
        ),
        isTrue,
        reason: 'include-shape nested omitted translate is +=0 so host '
            'dx leftover inches stay (10+30)*catalog scale',
      );

      final writer = VsdxWriter();
      final parser = DocumentParser();
      var doc = parser.parse(writer.emptyDocument());
      final laterId = doc.pages.first.nextFreeShapeId();
      doc = doc.replacePage(
        0,
        doc.pages.first.addShape(laterHost.copyWith(id: laterId)),
      );
      final leftover = parser
          .parse(
            writer.write(originalBytes: writer.emptyDocument(), edited: doc),
          )
          .pages
          .first
          .findShapeById(laterId)!;
      expect(
        minMoveX(leftover),
        closeTo(30 * canvasScale, 0.02),
        reason: 'a second save keeps leftover PinX Draw paints',
      );
      expect(
        leftover.children.any(
          (child) => (minMoveX(child) - 30 * canvasScale).abs() < 0.02,
        ),
        isTrue,
        reason: 'a second save keeps the later omitted-translate sibling',
      );
    },
  );

