        '<foreground>'
        '<rotate/>'
        '<rect x="20" y="0" w="10" h="10"/>'
        '<fill/>'
        '</foreground>'
        '</shape>',
        id: 523,
      );
      expect(
        minMoveX(omitted),
        closeTo(20 * canvasScale, 0.02),
        reason: 'omitted rotate is official identity skip; leftover '
            'early-return does not collapse PinX (`tokens.txt` PinX)',
      );

      final keep = decodeDrawioMxStencilXml(
        '<shape name="K" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<rect x="20" y="0" w="10" h="10"/>'
        '<fill/>'
        '</foreground>'
        '</shape>',
      );
      expect(
        minMoveX(keep),
        closeTo(20 * canvasScale, 0.02),
        reason: 'without a rotate node leftover stays unrotated',
      );

      final laterHost = decodeDrawioMxStencilXml(
        '<shape name="L" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<rotate theta="90" cx="0" cy="0" flipH="0" flipV="0"/>'
        '<rect x="20" y="0" w="10" h="10"/>'
        '<fill/>'
        '<rotate/>'
        '<rect x="20" y="0" w="10" h="10"/>'
        '<fill/>'
        '</foreground>'
        '</shape>',
      );
      expect(
        minMoveX(laterHost),
        closeTo(0, 0.02),
        reason: 'later omitted rotate is identity skip so Draw keeps the '
            'first leftover PinX (`tokens.txt` PinX / Angle)',
      );
      expect(
        laterHost.children.any((child) => minMoveX(child).abs() < 0.05),
        isTrue,
        reason: 'later omitted rotate leftover-bakes a sibling that stays '
            'on the previous leftover inches',
      );

      final flipHost = decodeDrawioMxStencilXml(
        '<shape name="F" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<rotate theta="0" cx="25" cy="0" flipH="1" flipV="0"/>'
        '<rect x="10" y="0" w="10" h="10"/>'
        '<fill/>'
        '<rotate/>'
        '<rect x="10" y="0" w="10" h="10"/>'
        '<fill/>'
        '</foreground>'
        '</shape>',
      );
      expect(
        minMoveX(flipHost),
        closeTo(40 * canvasScale, 0.02),
        reason: 'later omitted rotate keeps canvas flipH leftover inches',
      );
      expect(
        flipHost.children.any(
          (child) => (minMoveX(child) - 40 * canvasScale).abs() < 0.02,
        ),
        isTrue,
        reason: 'later omitted rotate leftover-bakes a flipH sibling so '
            'Draw does not un-mirror the second rail',
      );

      final includeHost = decodeDrawioMxStencilXml(
        '<shapes name="mxgraph.test">'
        '<shape name="host" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<rotate theta="90" cx="0" cy="0" flipH="0" flipV="0"/>'
        '<include-shape name="mxgraph.test.tile" x="20" y="0" w="10" h="10"/>'
        '</foreground>'
        '</shape>'
        '<shape name="tile" w="10" h="10" strokewidth="1">'
        '<foreground>'
        '<rotate/>'
        '<rect x="0" y="0" w="10" h="10"/>'
        '<fill/>'
        '</foreground>'
        '</shape>'
        '</shapes>',
      );
      expect(
        includeHost.children.any((child) => minMoveX(child).abs() < 0.05),
        isTrue,
        reason: 'include-shape nested omitted rotate is identity skip so '
            'host leftover-inch rotation stays; nested (20,0) maps to '
            '(0,20)',
      );

      final writer = VsdxWriter();
      final parser = DocumentParser();
      var doc = parser.parse(writer.emptyDocument());
      final laterId = doc.pages.first.nextFreeShapeId();
      doc = doc.replacePage(
        0,
        doc.pages.first.addShape(laterHost.copyWith(id: laterId)),
      );
      final leftover = parser
          .parse(
            writer.write(originalBytes: writer.emptyDocument(), edited: doc),
          )
          .pages
          .first
          .findShapeById(laterId)!;
      expect(
        minMoveX(leftover),
        closeTo(0, 0.02),
        reason: 'a second save keeps leftover rotated PinX Draw paints',
      );
      expect(
        leftover.children.any((child) => minMoveX(child).abs() < 0.05),
        isTrue,
        reason: 'a second save keeps the later omitted-rotate sibling',
      );
    },
  );

  test(
    'mxStencil mxXmlCanvas2D begin leftover discards unpainted path and resets lastX for LibreOffice',
    () {
      int commandCount(VsdxShape shape) {
        var n = 0;
        void walk(VsdxShape next) {
          for (final geometry in next.geometries) {
            n += geometry.commands.length;
          }
          for (final child in next.children) {
            walk(child);
          }
        }

        walk(shape);
        return n;
      }

      bool hasMoveThenLine(VsdxShape shape) {
        for (final geometry in shape.geometries) {
          if (geometry.commands.length >= 2 &&
              geometry.commands.first is MoveTo &&
              geometry.commands[1] is LineTo) {
            return true;
          }
        }
        return shape.children.any(hasMoveThenLine);
      }

      final omitted = decodeDrawioMxStencilXml(
        '<shape name="O" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<rect x="0" y="0" w="40" h="10"/>'
        '<begin/>'
        '<rect x="0" y="20" w="40" h="10"/>'
        '<fill/>'
        '</foreground>'
        '</shape>',
        id: 524,
      );
      expect(
        commandCount(omitted),
        5,
        reason: 'mxSvgCanvas2D.begin discards the unpainted path; leftover '
            'must not concatenate the dropped rect onto collectGeometry '
            'evenodd (`tokens.txt` FillForegnd)',
      );

      final keep = decodeDrawioMxStencilXml(
        '<shape name="K" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<rect x="0" y="0" w="40" h="10"/>'
        '<rect x="0" y="20" w="40" h="10"/>'
        '<fill/>'
        '</foreground>'
        '</shape>',
      );
      expect(
        commandCount(keep),
        10,
        reason: 'without a begin leftover concatenates both rects so Draw '
            'collectGeometry evenodd-paints both (`tokens.txt` FillForegnd)',
      );

      final laterHost = decodeDrawioMxStencilXml(
        '<shape name="L" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<rect x="0" y="0" w="40" h="10"/>'
        '<fill/>'
        '<rect x="50" y="0" w="40" h="10"/>'
        '<begin/>'
        '<rect x="0" y="20" w="40" h="10"/>'
        '<stroke/>'
        '</foreground>'
        '</shape>',
      );
      expect(
        laterHost.geometries.where((g) => !g.noFill).length,
        1,
        reason: 'first inherit fill stays after later begin discards the '
            'unpainted middle rect',
      );
      expect(
        laterHost.geometries.where((g) => !g.noLine).length,
        1,
        reason: 'later begin leftover does not glue the dropped rect onto '
            'the inherit stroke Draw collectLine paints (`tokens.txt` Line)',
      );

      final pen = decodeDrawioMxStencilXml(
        '<shape name="P" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<move x="40" y="0"/>'
        '<begin/>'
        '<line x="0" y="20"/>'
        '<stroke/>'
        '</foreground>'
        '</shape>',
      );
      expect(
        hasMoveThenLine(pen),
        isTrue,
        reason: 'official begin lastX/lastY is 0; leftover leftover-bakes '
            'MoveTo at the pen so Draw collectGeometry does not skip a '
            'LineTo-only section (`tokens.txt` Line)',
      );

      final includeHost = decodeDrawioMxStencilXml(
        '<shapes name="mxgraph.test">'
        '<shape name="host" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<rect x="0" y="0" w="40" h="10"/>'
        '<fill/>'
        '<include-shape name="mxgraph.test.tile" x="0" y="20" w="40" h="10"/>'
        '</foreground>'
        '</shape>'
        '<shape name="tile" w="40" h="10" strokewidth="1">'
        '<foreground>'
        '<rect x="0" y="0" w="40" h="10"/>'
        '<begin/>'
        '<rect x="0" y="0" w="20" h="10"/>'
        '<stroke/>'
        '</foreground>'
        '</shape>'
        '</shapes>',
      );
      expect(
        includeHost.geometries.where((g) => !g.noFill).length,
        1,
        reason: 'host inherit fill stays; nested begin does not drop it',
      );
      expect(
        includeHost.children.any(
          (child) =>
              child.geometries.any((g) => !g.noLine) &&
              child.geometries.every((g) => g.noFill),
        ),
        isTrue,
        reason: 'include-shape nested begin leftover-discards the tile '
            'unpainted rect so Draw collectLine strokes only the later rail',
      );

      final writer = VsdxWriter();
      final parser = DocumentParser();
      var doc = parser.parse(writer.emptyDocument());
      final laterId = doc.pages.first.nextFreeShapeId();
      doc = doc.replacePage(
        0,
        doc.pages.first.addShape(laterHost.copyWith(id: laterId)),
      );
      final leftover = parser
          .parse(
            writer.write(originalBytes: writer.emptyDocument(), edited: doc),
          )
          .pages
          .first
          .findShapeById(laterId)!;
      expect(
        leftover.geometries.where((g) => !g.noFill).length,
        1,
        reason: 'a second save keeps the first inherit fill Draw paints',
      );
      expect(
        leftover.geometries.where((g) => !g.noLine).length,
        1,
        reason: 'a second save keeps the later inherit stroke Draw paints',
      );
    },
  );

  test(
    'mxStencil mxXmlCanvas2D image omitted leftover FlipX and aspect for LibreOffice',
    () {
      const png =
          'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==';

      List<VsdxShape> imageShapes(VsdxShape shape) {
        return <VsdxShape>[
          if (shape.hasImage && shape.children.isEmpty) shape,
          for (final child in shape.children) ...imageShapes(child),
        ];
      }

      const canvasScale = 1.5 / 100;
      final omitted = decodeDrawioMxStencilXml(
        '<shape name="O" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<image src="data:image/png;base64,$png" '
        'x="0" y="0" w="40" h="10" flipH="1" flipV="1"/>'
        '<image src="data:image/png;base64,$png" '
        'x="50" y="0" w="40" h="10"/>'
        '</foreground>'
        '</shape>',
        id: 525,
      );
      expect(omitted.flipX, isFalse);
      expect(omitted.hasImage, isFalse);
      final omittedPics = imageShapes(omitted);
      expect(omittedPics, hasLength(2));
      expect(
        omittedPics.first.flipX,
        isTrue,
        reason: 'first canvas.image flipH leftover-bakes ForeignData FlipX '
            'so Draw collectForeignDataType transformFlips mirrors it '
            '(`tokens.txt` FlipX)',
      );
      expect(omittedPics.first.flipY, isTrue);
      expect(
        omittedPics.last.flipX,
        isFalse,
        reason: 'omitted flipH is not leftover canvas state; leftover must '
            'not inherit FlipX onto the later PNG Draw paints',
      );
      expect(omittedPics.last.flipY, isFalse);

      final keep = decodeDrawioMxStencilXml(
        '<shape name="K" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<image src="data:image/png;base64,$png" '
        'x="0" y="0" w="40" h="10"/>'
        '<image src="data:image/png;base64,$png" '
        'x="50" y="0" w="40" h="10"/>'
        '</foreground>'
        '</shape>',
      );
      final keepPics = imageShapes(keep);
      expect(keepPics, hasLength(2));
      expect(
        keepPics.every((pic) => !pic.flipX && !pic.flipY),
        isTrue,
        reason: 'without flipH leftover stays unmirrored ForeignData',
      );

      final laterHost = decodeDrawioMxStencilXml(
        '<shape name="L" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<image src="data:image/png;base64,$png" '
        'x="0" y="0" w="40" h="10" aspect="1"/>'
        '<image src="data:image/png;base64,$png" '
        'x="50" y="20" w="40" h="10"/>'
        '</foreground>'
        '</shape>',
      );
      final laterPics = imageShapes(laterHost);
      expect(laterPics, hasLength(2));
      expect(
        laterPics.first.imgWidthInches,
        closeTo(10 * canvasScale, 0.02),
        reason: 'first canvas.image aspect="1" leftover-bakes meet ImgWidth',
      );
      expect(
        laterPics.last.imgWidthInches,
        closeTo(40 * canvasScale, 0.02),
        reason: 'later omitted aspect leftover-bakes stretched Img* so Draw '
            'collectForeignDataType does not letterbox both PNGs '
            '(`tokens.txt` has no image aspect)',
      );

      final includeHost = decodeDrawioMxStencilXml(
        '<shapes name="mxgraph.test">'
        '<shape name="host" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<image src="data:image/png;base64,$png" '
        'x="0" y="0" w="40" h="10" flipH="1"/>'
        '<include-shape name="mxgraph.test.tile" x="50" y="0" w="40" h="10"/>'
        '</foreground>'
        '</shape>'
        '<shape name="tile" w="40" h="10" strokewidth="1">'
        '<foreground>'
        '<image src="data:image/png;base64,$png" '
        'x="0" y="0" w="40" h="10"/>'
        '</foreground>'
        '</shape>'
        '</shapes>',
      );
      final nestedPics = imageShapes(includeHost);
      expect(nestedPics, hasLength(2));
      expect(nestedPics.first.flipX, isTrue);
      expect(
        nestedPics.last.flipX,
        isFalse,
        reason: 'include-shape nested omitted flipH does not inherit host '
            'ForeignData FlipX Draw transformFlips',
      );

      final writer = VsdxWriter();
      final parser = DocumentParser();
      var doc = parser.parse(writer.emptyDocument());
      final omittedId = doc.pages.first.nextFreeShapeId();
      doc = doc.replacePage(
        0,
        doc.pages.first.addShape(omitted.copyWith(id: omittedId)),
      );
      final laterId = doc.pages.first.nextFreeShapeId();
      doc = doc.replacePage(
        0,
        doc.pages.first.addShape(laterHost.copyWith(id: laterId)),
      );
      final leftoverDoc = parser.parse(
        writer.write(originalBytes: writer.emptyDocument(), edited: doc),
      );
      final leftoverOmitted = imageShapes(
        leftoverDoc.pages.first.findShapeById(omittedId)!,
      );
      expect(leftoverOmitted, hasLength(2));
      expect(
        leftoverOmitted.first.flipX,
        isTrue,
        reason: 'a second save keeps first ForeignData FlipX Draw paints',
      );
      expect(
        leftoverOmitted.last.flipX,
        isFalse,
        reason: 'a second save keeps the later omitted-flipH sibling',
      );
      final leftoverLater = imageShapes(
        leftoverDoc.pages.first.findShapeById(laterId)!,
      );
      expect(
        leftoverLater.first.imgWidthInches,
        closeTo(10 * canvasScale, 0.02),
        reason: 'a second save keeps leftover meet ImgWidth Draw paints',
      );
      expect(
        leftoverLater.last.imgWidthInches,
        closeTo(40 * canvasScale, 0.02),
        reason: 'a second save keeps the later omitted-aspect sibling',
      );
    },
  );

  test(
    'mxStencil include-shape omitted leftover skips nested Width for LibreOffice',
    () {
      int nestedStrokeCount(VsdxShape shape) {
        var n = 0;
        void walk(VsdxShape next) {
          for (final child in next.children) {
            if (child.line.hasLine) n++;
            walk(child);
          }
        }

        walk(shape);
        return n;
      }

      bool hasNestedFill(VsdxShape shape) {
        for (final child in shape.children) {
          if (child.fill.hasFill) return true;
          if (hasNestedFill(child)) return true;
        }
        return false;
      }

      const canvasScale = 1.5 / 100;
      final omitted = decodeDrawioMxStencilXml(
        '<shapes name="mxgraph.test">'
        '<shape name="host" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<rect x="0" y="0" w="40" h="10"/>'
        '<fill/>'
        '<include-shape name="mxgraph.test.tile"/>'
        '</foreground>'
        '</shape>'
        '<shape name="tile" w="40" h="10" strokewidth="1">'
        '<foreground>'
        '<rect x="0" y="0" w="40" h="10"/>'
        '<stroke/>'
        '</foreground>'
        '</shape>'
        '</shapes>',
        id: 526,
      );
      expect(
        omitted.fill.hasFill,
        isTrue,
        reason: 'host inherit fill stays when omitted include is skipped',
      );
      expect(
        nestedStrokeCount(omitted),
        0,
        reason: 'official drawChildren skips w==0; leftover must not fall '
            'through to nested stencil Width so Draw collectGeometry does '
            'not paint the tile (`tokens.txt` Width)',
      );

      final omittedW = decodeDrawioMxStencilXml(
        '<shapes name="mxgraph.test">'
        '<shape name="host" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<rect x="0" y="0" w="40" h="10"/>'
        '<fill/>'
        '<include-shape name="mxgraph.test.tile" x="0" y="20" h="10"/>'
        '</foreground>'
        '</shape>'
        '<shape name="tile" w="40" h="10" strokewidth="1">'
        '<foreground>'
        '<rect x="0" y="0" w="40" h="10"/>'
        '<stroke/>'
        '</foreground>'
        '</shape>'
        '</shapes>',
      );
      expect(
        nestedStrokeCount(omittedW),
        0,
        reason: 'omitted w is Number(null)=0; leftover must not use nested '
            'stencil w as the include box',
      );

      final keep = decodeDrawioMxStencilXml(
        '<shapes name="mxgraph.test">'
        '<shape name="host" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<rect x="0" y="0" w="40" h="10"/>'
        '<fill/>'
        '<include-shape name="mxgraph.test.tile" x="0" y="20" w="40" h="10"/>'
        '</foreground>'
        '</shape>'
        '<shape name="tile" w="40" h="10" strokewidth="1">'
        '<foreground>'
        '<rect x="0" y="0" w="40" h="10"/>'
        '<stroke/>'
        '</foreground>'
        '</shape>'
        '</shapes>',
      );
      expect(keep.fill.hasFill, isTrue);
      expect(
        nestedStrokeCount(keep),
        1,
        reason: 'with w/h leftover still paints the nested tile Draw '
            'collectLine strokes (`tokens.txt` Line)',
      );
      expect(
        keep.children.any((child) {
          if (!child.line.hasLine) return false;
          var minY = double.infinity;
          for (final geometry in child.geometries) {
            for (final command in geometry.commands) {
              if (command is MoveTo) minY = math.min(minY, command.y);
            }
          }
          return (minY - (100 - 20) * canvasScale).abs() < 0.02;
        }),
        isTrue,
        reason: 'include y=20 leftover-bakes nested MoveTo so Draw '
            'collectGeometry paints the tile below the host fill '
            '(`tokens.txt` PinX)',
      );

      final laterHost = decodeDrawioMxStencilXml(
        '<shapes name="mxgraph.test">'
        '<shape name="host" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<include-shape name="mxgraph.test.tile" x="0" y="0" w="40" h="10"/>'
        '<include-shape name="mxgraph.test.tile"/>'
        '</foreground>'
        '</shape>'
        '<shape name="tile" w="40" h="10" strokewidth="1">'
        '<foreground>'
        '<rect x="0" y="0" w="40" h="10"/>'
        '<stroke/>'
        '</foreground>'
        '</shape>'
        '</shapes>',
      );
      expect(
        nestedStrokeCount(laterHost),
        1,
        reason: 'later omitted include does not inherit the previous '
            'include box so Draw collectGeometry paints one tile',
      );

      final includeHost = decodeDrawioMxStencilXml(
        '<shapes name="mxgraph.test">'
        '<shape name="host" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<include-shape name="mxgraph.test.tile" x="0" y="0" w="40" h="10"/>'
        '</foreground>'
        '</shape>'
        '<shape name="tile" w="40" h="10" strokewidth="1">'
        '<foreground>'
        '<rect x="0" y="0" w="40" h="10"/>'
        '<stroke/>'
        '<include-shape name="mxgraph.test.inner"/>'
        '</foreground>'
        '</shape>'
        '<shape name="inner" w="20" h="10" strokewidth="1">'
        '<foreground>'
        '<rect x="0" y="0" w="20" h="10"/>'
        '<fill/>'
        '</foreground>'
        '</shape>'
        '</shapes>',
      );
      expect(
        nestedStrokeCount(includeHost),
        1,
        reason: 'host include with w/h still leftover-bakes the tile stroke',
      );
      expect(
        hasNestedFill(includeHost),
        isFalse,
        reason: 'include-shape nested omitted include skips the inner tile '
            'so Draw collectFillAndShadow does not inherit nested Width',
      );

      final writer = VsdxWriter();
      final parser = DocumentParser();
      var doc = parser.parse(writer.emptyDocument());
      final laterId = doc.pages.first.nextFreeShapeId();
      doc = doc.replacePage(
        0,
        doc.pages.first.addShape(laterHost.copyWith(id: laterId)),
      );
      final leftover = parser
          .parse(
            writer.write(originalBytes: writer.emptyDocument(), edited: doc),
          )
          .pages
          .first
          .findShapeById(laterId)!;
      expect(
        nestedStrokeCount(leftover),
        1,
        reason: 'a second save keeps the first nested tile Draw paints',
      );
    },
  );

  test(
    'mxStencil mxXmlCanvas2D text omitted leftover wrap and clip TxtWidth for LibreOffice',
    () {
      const str = 'MMMMMMMMMMMMMMMMMMMM';
      const canvasScale = 1.5 / 100;
      const boxW = 20.0;

      List<VsdxShape> glyphs(VsdxShape shape) {
        return <VsdxShape>[
          if ((shape.text ?? '').contains('MMMM') && shape.children.isEmpty)
            shape,
          for (final child in shape.children) ...glyphs(child),
        ];
      }

      double txtWidth(VsdxShape shape) =>
          shape.richText.textBlock.widthInches ?? shape.width;

      final omitted = decodeDrawioMxStencilXml(
        '<shape name="O" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<text str="$str" x="0" y="0" w="$boxW" h="20" '
        'align="left" valign="top" wrap="0" clip="1"/>'
        '<text str="$str" x="0" y="30" w="$boxW" h="20" '
        'align="left" valign="top" wrap="0"/>'
        '</foreground>'
        '</shape>',
        id: 527,
      );
      final omittedGlyphs = glyphs(omitted);
      expect(omittedGlyphs, hasLength(2));
      expect(
        omittedGlyphs.first.wordWrap,
        isTrue,
        reason: 'first canvas.text clip leftover-keeps TxtWidth so Draw '
            'collectTextBlock wraps inside the clip frame (`tokens.txt` '
            'has no veWordWrap; svg:width is TxtWidth)',
      );
      expect(
        omittedGlyphs.last.wordWrap,
        isFalse,
        reason: 'omitted clip is not leftover canvas state; leftover must '
            'not keep TxtWidth on the later glyph Draw paints',
      );

      final keep = decodeDrawioMxStencilXml(
        '<shape name="K" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<text str="$str" x="0" y="0" w="$boxW" h="20" '
        'align="left" valign="top" wrap="0"/>'
        '<text str="$str" x="0" y="30" w="$boxW" h="20" '
        'align="left" valign="top" wrap="0"/>'
        '</foreground>'
        '</shape>',
      );
      expect(
        glyphs(keep).every((glyph) => !glyph.wordWrap),
        isTrue,
        reason: 'without clip leftover wrap=0 expands TxtWidth on save',
      );

      final laterHost = decodeDrawioMxStencilXml(
        '<shape name="L" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<text str="$str" x="0" y="0" w="$boxW" h="20" '
        'align="left" valign="top" wrap="1"/>'
        '<text str="$str" x="0" y="30" w="$boxW" h="20" '
        'align="left" valign="top"/>'
        '</foreground>'
        '</shape>',
      );
      final laterGlyphs = glyphs(laterHost);
      expect(laterGlyphs, hasLength(2));
      expect(
        laterGlyphs.first.wordWrap,
        isTrue,
        reason: 'first canvas.text wrap leftover-keeps the cell box',
      );
      expect(
        laterGlyphs.last.wordWrap,
        isFalse,
        reason: 'later omitted wrap leftover-bakes overflow TxtWidth so '
            'Draw collectTextBlock does not wrap both glyphs',
      );

      final includeHost = decodeDrawioMxStencilXml(
        '<shapes name="mxgraph.test">'
        '<shape name="host" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<text str="$str" x="0" y="0" w="$boxW" h="20" '
        'align="left" valign="top" wrap="0" clip="1"/>'
        '<include-shape name="mxgraph.test.tile" x="0" y="40" w="40" h="20"/>'
        '</foreground>'
        '</shape>'
        '<shape name="tile" w="40" h="20" strokewidth="1">'
        '<foreground>'
        '<text str="$str" x="0" y="0" w="$boxW" h="20" '
        'align="left" valign="top" wrap="0"/>'
        '</foreground>'
        '</shape>'
        '</shapes>',
      );
      final nestedGlyphs = glyphs(includeHost);
      expect(nestedGlyphs, hasLength(2));
      expect(nestedGlyphs.first.wordWrap, isTrue);
      expect(
        nestedGlyphs.last.wordWrap,
        isFalse,
        reason: 'include-shape nested omitted clip does not inherit host '
            'TxtWidth Draw collectTextBlock',
      );

      final writer = VsdxWriter();
      final parser = DocumentParser();
      var doc = parser.parse(writer.emptyDocument());
      final omittedId = doc.pages.first.nextFreeShapeId();
      doc = doc.replacePage(
        0,
        doc.pages.first.addShape(omitted.copyWith(id: omittedId)),
      );
      final laterId = doc.pages.first.nextFreeShapeId();
      doc = doc.replacePage(
        0,
        doc.pages.first.addShape(laterHost.copyWith(id: laterId)),
      );
      final leftoverDoc = parser.parse(
        writer.write(originalBytes: writer.emptyDocument(), edited: doc),
      );
      final leftoverOmitted = glyphs(
        leftoverDoc.pages.first.findShapeById(omittedId)!,
      );
      expect(
        txtWidth(leftoverOmitted.first),
        closeTo(boxW * canvasScale, 0.02),
        reason: 'a second save keeps leftover clip TxtWidth Draw paints',
      );
      expect(
        txtWidth(leftoverOmitted.last),
        greaterThan(boxW * canvasScale + 0.2),
        reason: 'a second save keeps the later omitted-clip sibling',
      );
      final leftoverLater = glyphs(
        leftoverDoc.pages.first.findShapeById(laterId)!,
      );
      expect(
        txtWidth(leftoverLater.first),
        closeTo(boxW * canvasScale, 0.02),
        reason: 'a second save keeps leftover wrap TxtWidth Draw paints',
      );
      expect(
        txtWidth(leftoverLater.last),
        greaterThan(boxW * canvasScale + 0.2),
        reason: 'a second save keeps the later omitted-wrap sibling',
      );
    },
  );

  test(
    'mxStencil mxXmlCanvas2D text omitted leftover dir Flags for LibreOffice',
    () {
      VsdxShape? glyphContaining(VsdxShape shape, String text) {
        if ((shape.text ?? '').contains(text)) return shape;
        for (final child in shape.children) {
          final nested = glyphContaining(child, text);
          if (nested != null) return nested;
        }
        return null;
      }

      int flagsOf(VsdxShape shape) => shape.richText.runs.first.paraStyle.flags;

      int dirOf(VsdxShape shape) => shape.richText.textBlock.textDirection;

      final omitted = decodeDrawioMxStencilXml(
        '<shape name="O" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<text str="AB" x="0" y="0" w="40" h="20" '
        'align="left" valign="top" dir="rtl"/>'
        '<text str="CD" x="0" y="30" w="40" h="20" '
        'align="left" valign="top"/>'
        '</foreground>'
        '</shape>',
        id: 528,
      );
      expect(
        flagsOf(glyphContaining(omitted, 'AB')!),
        1,
        reason: 'first canvas.text dir=rtl leftover-bakes Paragraph Flags '
            'so Draw `_fillParagraphProperties` swaps left to end '
            '(`tokens.txt` Flags)',
      );
      expect(
        flagsOf(glyphContaining(omitted, 'CD')!),
        0,
        reason: 'omitted dir is not leftover canvas state; leftover must '
            'not keep Flags on the later glyph Draw paints',
      );

      final keep = decodeDrawioMxStencilXml(
        '<shape name="K" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<text str="AB" x="0" y="0" w="40" h="20" align="left" valign="top"/>'
        '<text str="CD" x="0" y="30" w="40" h="20" align="left" valign="top"/>'
        '</foreground>'
        '</shape>',
      );
      expect(flagsOf(glyphContaining(keep, 'AB')!), 0);
      expect(
        flagsOf(glyphContaining(keep, 'CD')!),
        0,
        reason: 'without dir leftover stays LTR Paragraph Flags',
      );

      final laterHost = decodeDrawioMxStencilXml(
        '<shape name="L" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<text str="AB" x="0" y="0" w="20" h="40" '
        'align="left" valign="top" dir="vertical-lr"/>'
        '<text str="CD" x="0" y="50" w="40" h="20" '
        'align="left" valign="top"/>'
        '</foreground>'
        '</shape>',
      );
      expect(
        dirOf(glyphContaining(laterHost, 'AB')!),
        1,
        reason: 'first canvas.text dir vertical-* leftover-bakes '
            'TextDirection so Draw collectTextBlock is vertical',
      );
      expect(
        dirOf(glyphContaining(laterHost, 'CD')!),
        0,
        reason: 'later omitted dir leftover-bakes LTR TextDirection so '
            'Draw does not vertical both glyphs (`tokens.txt` '
            'TextDirection)',
      );

      final includeHost = decodeDrawioMxStencilXml(
        '<shapes name="mxgraph.test">'
        '<shape name="host" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<text str="AB" x="0" y="0" w="40" h="20" '
        'align="left" valign="top" dir="rtl"/>'
        '<include-shape name="mxgraph.test.tile" x="0" y="30" w="40" h="20"/>'
        '</foreground>'
        '</shape>'
        '<shape name="tile" w="40" h="20" strokewidth="1">'
        '<foreground>'
        '<text str="CD" x="0" y="0" w="40" h="20" '
        'align="left" valign="top"/>'
        '</foreground>'
        '</shape>'
        '</shapes>',
      );
      expect(flagsOf(glyphContaining(includeHost, 'AB')!), 1);
      expect(
        flagsOf(glyphContaining(includeHost, 'CD')!),
        0,
        reason: 'include-shape nested omitted dir does not inherit host '
            'Paragraph Flags Draw `_fillParagraphProperties`',
      );

      final writer = VsdxWriter();
      final parser = DocumentParser();
      var doc = parser.parse(writer.emptyDocument());
      final omittedId = doc.pages.first.nextFreeShapeId();
      doc = doc.replacePage(
        0,
        doc.pages.first.addShape(omitted.copyWith(id: omittedId)),
      );
      final laterId = doc.pages.first.nextFreeShapeId();
      doc = doc.replacePage(
        0,
        doc.pages.first.addShape(laterHost.copyWith(id: laterId)),
      );
      final leftoverDoc = parser.parse(
        writer.write(originalBytes: writer.emptyDocument(), edited: doc),
      );
      expect(
        flagsOf(
          glyphContaining(
            leftoverDoc.pages.first.findShapeById(omittedId)!,
            'AB',
          )!,
        ),
        1,
        reason: 'a second save keeps leftover Paragraph Flags Draw paints',
      );
      expect(
        flagsOf(
          glyphContaining(
            leftoverDoc.pages.first.findShapeById(omittedId)!,
            'CD',
          )!,
        ),
        0,
        reason: 'a second save keeps the later omitted-dir sibling',
      );
      expect(
        dirOf(
          glyphContaining(
            leftoverDoc.pages.first.findShapeById(laterId)!,
            'AB',
          )!,
        ),
        0,
        reason: 'a save bakes TextDirection so canvas reopen does not '
            'rotate twice',
      );
      expect(
        glyphContaining(
          leftoverDoc.pages.first.findShapeById(laterId)!,
          'AB',
        )!
            .richText
            .textBlock
            .angleRad,
        closeTo(-math.pi / 2, 0.05),
        reason: 'a second save keeps leftover TxtAngle Draw '
            'librevenge:rotate paints (`tokens.txt` TxtAngle)',
      );
      expect(
        glyphContaining(
          leftoverDoc.pages.first.findShapeById(laterId)!,
          'CD',
        )!
            .richText
            .textBlock
            .angleRad
            .abs(),
        lessThan(0.05),
        reason: 'a second save keeps the later omitted-vertical sibling '
            'unrotated',
      );
    },
  );

