        VsdxHorzAlign.center,
        reason: 'first canvas.text align leftover-bakes HorzAlign so Draw '
            '_fillParagraphProperties emits fo:text-align=center '
            '(`tokens.txt` HorzAlign)',
      );
      expect(vertOf(omitted, 'AB'), VsdxVertAlign.middle);
      expect(
        horzOf(omitted, 'CD'),
