  test(
    'mxStencil mxXmlCanvas2D text omitted leftover overflow TxtWidth for LibreOffice',
    () {
      const str = 'MMMMMMMMMMMMMMMMMMMM';
      const canvasScale = 1.5 / 100;
      const boxW = 20.0;

      List<VsdxShape> glyphs(VsdxShape shape) {
        return <VsdxShape>[
          if ((shape.text ?? '').contains('MMMM') && shape.children.isEmpty)
            shape,
          for (final child in shape.children) ...glyphs(child),
        ];
      }

      double txtWidth(VsdxShape shape) =>
          shape.richText.textBlock.widthInches ?? shape.width;

      final omitted = decodeDrawioMxStencilXml(
        '<shape name="O" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<text str="$str" x="0" y="0" w="$boxW" h="20" '
        'align="left" valign="top" wrap="0" overflow="fill"/>'
        '<text str="$str" x="0" y="30" w="$boxW" h="20" '
        'align="left" valign="top" wrap="0"/>'
        '</foreground>'
        '</shape>',
        id: 531,
      );
      final omittedGlyphs = glyphs(omitted);
      expect(omittedGlyphs, hasLength(2));
      expect(
        omittedGlyphs.first.wordWrap,
        isTrue,
        reason: 'first canvas.text overflow=fill leftover-keeps TxtWidth so '
            'Draw collectTextBlock wraps inside the cell box '
            '(`tokens.txt` has no veWordWrap; svg:width is TxtWidth)',
      );
      expect(
        omittedGlyphs.last.wordWrap,
        isFalse,
        reason: 'omitted overflow is not leftover canvas state; leftover '
            'must not keep TxtWidth on the later glyph Draw paints',
      );

      final keep = decodeDrawioMxStencilXml(
        '<shape name="K" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<text str="$str" x="0" y="0" w="$boxW" h="20" '
        'align="left" valign="top" wrap="0"/>'
        '<text str="$str" x="0" y="30" w="$boxW" h="20" '
        'align="left" valign="top" wrap="0"/>'
        '</foreground>'
        '</shape>',
      );
      expect(
        glyphs(keep).every((glyph) => !glyph.wordWrap),
        isTrue,
        reason: 'without overflow leftover wrap=0 expands TxtWidth on save',
      );

      final laterHost = decodeDrawioMxStencilXml(
        '<shape name="L" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<text str="$str" x="0" y="0" w="$boxW" h="20" '
        'align="left" valign="top" wrap="0" overflow="width"/>'
        '<text str="$str" x="0" y="30" w="$boxW" h="20" '
        'align="left" valign="top" wrap="0"/>'
        '</foreground>'
        '</shape>',
      );
      final laterGlyphs = glyphs(laterHost);
      expect(laterGlyphs, hasLength(2));
      expect(
        laterGlyphs.first.wordWrap,
        isTrue,
        reason: 'first canvas.text overflow=width leftover-keeps the cell box',
      );
      expect(
        laterGlyphs.last.wordWrap,
        isFalse,
        reason: 'later omitted overflow leftover-bakes overflow TxtWidth so '
            'Draw collectTextBlock does not clip both glyphs',
      );

      final includeHost = decodeDrawioMxStencilXml(
        '<shapes name="mxgraph.test">'
        '<shape name="host" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<text str="$str" x="0" y="0" w="$boxW" h="20" '
        'align="left" valign="top" wrap="0" overflow="fill"/>'
        '<include-shape name="mxgraph.test.tile" x="0" y="40" w="40" h="20"/>'
        '</foreground>'
        '</shape>'
        '<shape name="tile" w="40" h="20" strokewidth="1">'
        '<foreground>'
        '<text str="$str" x="0" y="0" w="$boxW" h="20" '
        'align="left" valign="top" wrap="0"/>'
        '</foreground>'
        '</shape>'
        '</shapes>',
      );
      final nestedGlyphs = glyphs(includeHost);
      expect(nestedGlyphs, hasLength(2));
      expect(nestedGlyphs.first.wordWrap, isTrue);
      expect(
        nestedGlyphs.last.wordWrap,
        isFalse,
        reason: 'include-shape nested omitted overflow does not inherit host '
            'TxtWidth Draw collectTextBlock',
      );

      final writer = VsdxWriter();
      final parser = DocumentParser();
      var doc = parser.parse(writer.emptyDocument());
      final omittedId = doc.pages.first.nextFreeShapeId();
      doc = doc.replacePage(
        0,
        doc.pages.first.addShape(omitted.copyWith(id: omittedId)),
      );
      final laterId = doc.pages.first.nextFreeShapeId();
      doc = doc.replacePage(
        0,
        doc.pages.first.addShape(laterHost.copyWith(id: laterId)),
      );
      final leftoverDoc = parser.parse(
        writer.write(originalBytes: writer.emptyDocument(), edited: doc),
      );
      final leftoverOmitted = glyphs(
        leftoverDoc.pages.first.findShapeById(omittedId)!,
      );
      expect(
        txtWidth(leftoverOmitted.first),
        closeTo(boxW * canvasScale, 0.02),
        reason: 'a second save keeps leftover overflow TxtWidth Draw paints',
      );
      expect(
        txtWidth(leftoverOmitted.last),
        greaterThan(boxW * canvasScale + 0.2),
        reason: 'a second save keeps the later omitted-overflow sibling',
      );
      final leftoverLater = glyphs(
        leftoverDoc.pages.first.findShapeById(laterId)!,
      );
      expect(
        txtWidth(leftoverLater.first),
        closeTo(boxW * canvasScale, 0.02),
        reason: 'a second save keeps leftover overflow=width TxtWidth',
      );
      expect(
        txtWidth(leftoverLater.last),
        greaterThan(boxW * canvasScale + 0.2),
        reason: 'a second save keeps the later omitted-overflow sibling',
      );
    },
  );

  test(
    'mxStencil strokewidth omitted leftover fixed LineWeight for LibreOffice',
    () {
      List<double> lineWeights(VsdxShape shape) {
        final weights = <double>[];
        void walk(VsdxShape next) {
          if (next.line.hasLine) weights.add(next.line.weightInches);
          for (final child in next.children) {
            walk(child);
          }
        }

        walk(shape);
        weights.sort();
        return weights;
      }

      const canvasScale = 1.5 / 100;
      const nestedMinScale = (80 / 10) * canvasScale;
      const width = 2.0;
      final hairline = width * canvasScale;
      final scaled = width * nestedMinScale;

      final omitted = decodeDrawioMxStencilXml(
        '<shapes name="mxgraph.test">'
        '<shape name="host" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<include-shape name="mxgraph.test.tile" x="10" y="10" w="80" h="80"/>'
        '</foreground>'
        '</shape>'
        '<shape name="tile" w="10" h="10" strokewidth="1">'
        '<foreground>'
        '<strokewidth width="2" fixed="1"/>'
        '<ellipse x="0" y="0" w="4" h="4"/>'
        '<stroke/>'
        '<strokewidth width="2"/>'
        '<rect x="5" y="5" w="4" h="4"/>'
        '<stroke/>'
        '</foreground>'
        '</shape>'
        '</shapes>',
        id: 532,
      );
      expect(
        lineWeights(omitted),
        [closeTo(hairline, 1e-6), closeTo(scaled, 1e-6)],
        reason: 'omitted fixed is nested minScale; leftover must not keep '
            'the first canvas-pixel hairline on the later rail Draw '
            'collectLine paints (`tokens.txt` LineWeight)',
      );

      final keep = decodeDrawioMxStencilXml(
        '<shapes name="mxgraph.test">'
        '<shape name="host" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<include-shape name="mxgraph.test.tile" x="10" y="10" w="80" h="80"/>'
        '</foreground>'
        '</shape>'
        '<shape name="tile" w="10" h="10" strokewidth="1">'
        '<foreground>'
        '<strokewidth width="2"/>'
        '<ellipse x="0" y="0" w="4" h="4"/>'
        '<stroke/>'
        '<rect x="5" y="5" w="4" h="4"/>'
        '<stroke/>'
        '</foreground>'
        '</shape>'
        '</shapes>',
      );
      expect(
        lineWeights(keep),
        everyElement(closeTo(scaled, 1e-6)),
        reason: 'without fixed leftover stays nested minScale LineWeight',
      );

      final laterHost = decodeDrawioMxStencilXml(
        '<shapes name="mxgraph.test">'
        '<shape name="host" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<include-shape name="mxgraph.test.tile" x="10" y="10" w="80" h="80"/>'
        '</foreground>'
        '</shape>'
        '<shape name="tile" w="10" h="10" strokewidth="1">'
        '<foreground>'
        '<strokewidth width="2"/>'
        '<ellipse x="0" y="0" w="4" h="4"/>'
        '<stroke/>'
        '<strokewidth width="2" fixed="1"/>'
        '<rect x="5" y="5" w="4" h="4"/>'
        '<stroke/>'
        '</foreground>'
        '</shape>'
        '</shapes>',
      );
      expect(
        lineWeights(laterHost),
        [closeTo(hairline, 1e-6), closeTo(scaled, 1e-6)],
        reason: 'later fixed leftover-bakes a hairline sibling so Draw '
            'does not scale both rails (`tokens.txt` LineWeight)',
      );

      final includeHost = decodeDrawioMxStencilXml(
        '<shapes name="mxgraph.test">'
        '<shape name="host" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<strokewidth width="2" fixed="1"/>'
        '<rect x="0" y="0" w="10" h="10"/>'
        '<stroke/>'
        '<include-shape name="mxgraph.test.tile" x="10" y="10" w="80" h="80"/>'
        '</foreground>'
        '</shape>'
        '<shape name="tile" w="10" h="10" strokewidth="1">'
        '<foreground>'
        '<strokewidth width="2"/>'
        '<ellipse x="0" y="0" w="10" h="10"/>'
        '<stroke/>'
        '</foreground>'
        '</shape>'
        '</shapes>',
      );
      expect(includeHost.line.weightInches, closeTo(hairline, 1e-6));
      expect(
        includeHost.children.any(
          (child) => (child.line.weightInches - scaled).abs() < 1e-6,
        ),
        isTrue,
        reason: 'include-shape nested omitted fixed leftover-bakes nested '
            'minScale so Draw collectLine does not inherit host hairline',
      );

      final writer = VsdxWriter();
      final parser = DocumentParser();
      var doc = parser.parse(writer.emptyDocument());
      final omittedId = doc.pages.first.nextFreeShapeId();
      doc = doc.replacePage(
        0,
        doc.pages.first.addShape(omitted.copyWith(id: omittedId)),
      );
      final laterId = doc.pages.first.nextFreeShapeId();
      doc = doc.replacePage(
        0,
        doc.pages.first.addShape(laterHost.copyWith(id: laterId)),
      );
      final leftoverDoc = parser.parse(
        writer.write(originalBytes: writer.emptyDocument(), edited: doc),
      );
      expect(
        lineWeights(leftoverDoc.pages.first.findShapeById(omittedId)!),
        [closeTo(hairline, 1e-6), closeTo(scaled, 1e-6)],
        reason: 'a second save keeps leftover LineWeight Draw paints',
      );
      expect(
        lineWeights(leftoverDoc.pages.first.findShapeById(laterId)!),
        [closeTo(hairline, 1e-6), closeTo(scaled, 1e-6)],
        reason: 'a second save keeps the later fixed sibling',
      );
    },
  );

  test(
    'mxStencil mxXmlCanvas2D text omitted leftover format Character Style for LibreOffice',
    () {
      VsdxShape? glyphContaining(VsdxShape shape, String text) {
        if ((shape.text ?? '').contains(text)) return shape;
        for (final child in shape.children) {
          final nested = glyphContaining(child, text);
          if (nested != null) return nested;
        }
        return null;
      }

      VsdxTextRun? runContaining(VsdxShape shape, String text) {
        for (final run in shape.richText.runs) {
          if (run.text.contains(text)) return run;
        }
        for (final child in shape.children) {
          final nested = runContaining(child, text);
          if (nested != null) return nested;
        }
        return null;
      }

      final omitted = decodeDrawioMxStencilXml(
        '<shape name="O" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<text format="html" str="&lt;b&gt;AB&lt;/b&gt;" x="0" y="0" '
        'w="40" h="20" align="left" valign="top"/>'
        '<text str="&lt;b&gt;CD&lt;/b&gt;" x="0" y="30" '
        'w="40" h="20" align="left" valign="top"/>'
        '</foreground>'
        '</shape>',
        id: 533,
      );
      expect(
        glyphContaining(omitted, 'AB')!.text,
        'AB',
      );
      expect(
        runContaining(glyphContaining(omitted, 'AB')!, 'AB')!
            .charStyle
            .style
            .bold,
        isTrue,
      );
      expect(
        glyphContaining(omitted, '<b>CD</b>')!.text,
        '<b>CD</b>',
        reason: 'omitted format is official empty format; leftover must not '
            'keep html parse so Draw collectCharIX does not bold the later '
            'markup (`tokens.txt` Character Style → fo:font-weight)',
      );
      expect(
        runContaining(glyphContaining(omitted, '<b>CD</b>')!, 'CD')!
            .charStyle
            .style
            .bold,
        isFalse,
      );

      final keep = decodeDrawioMxStencilXml(
        '<shape name="K" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<text str="AB" x="0" y="0" w="40" h="20" align="left" valign="top"/>'
        '<text str="&lt;b&gt;CD&lt;/b&gt;" x="0" y="30" '
        'w="40" h="20" align="left" valign="top"/>'
        '</foreground>'
        '</shape>',
      );
      expect(glyphContaining(keep, 'AB')!.text, 'AB');
      expect(
        glyphContaining(keep, '<b>CD</b>')!.text,
        '<b>CD</b>',
        reason: 'without format leftover keeps markup as collectText',
      );

      final later = decodeDrawioMxStencilXml(
        '<shape name="L" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<text str="AB" x="0" y="0" w="40" h="20" align="left" valign="top"/>'
        '<text format="html" str="&lt;b&gt;CD&lt;/b&gt;" x="0" y="30" '
        'w="40" h="20" align="left" valign="top"/>'
        '</foreground>'
        '</shape>',
      );
      expect(
        runContaining(glyphContaining(later, 'AB')!, 'AB')!
            .charStyle
            .style
            .bold,
        isFalse,
      );
      expect(
        runContaining(glyphContaining(later, 'CD')!, 'CD')!
            .charStyle
            .style
            .bold,
        isTrue,
        reason: 'later format=html leftover-bakes Style.bold on a sibling so '
            'Draw does not bold both glyphs',
      );

      final includeHost = decodeDrawioMxStencilXml(
        '<shapes name="mxgraph.test">'
        '<shape name="host" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<text format="html" str="&lt;b&gt;AB&lt;/b&gt;" x="0" y="0" '
        'w="40" h="20" align="left" valign="top"/>'
        '<include-shape name="mxgraph.test.tile" x="0" y="30" w="40" h="20"/>'
        '</foreground>'
        '</shape>'
        '<shape name="tile" w="40" h="20" strokewidth="1">'
        '<foreground>'
        '<text str="&lt;b&gt;CD&lt;/b&gt;" x="0" y="0" '
        'w="40" h="20" align="left" valign="top"/>'
        '</foreground>'
        '</shape>'
        '</shapes>',
      );
      expect(
        runContaining(glyphContaining(includeHost, 'AB')!, 'AB')!
            .charStyle
            .style
            .bold,
        isTrue,
      );
      expect(
        glyphContaining(includeHost, '<b>CD</b>')!.text,
        '<b>CD</b>',
        reason: 'include-shape nested omitted format leftover-bakes markup '
            'so Draw does not inherit host html Style.bold',
      );

      final writer = VsdxWriter();
      final parser = DocumentParser();
      var doc = parser.parse(writer.emptyDocument());
      final omittedId = doc.pages.first.nextFreeShapeId();
      doc = doc.replacePage(
        0,
        doc.pages.first.addShape(omitted.copyWith(id: omittedId)),
      );
      final laterId = doc.pages.first.nextFreeShapeId();
      doc = doc.replacePage(
        0,
        doc.pages.first.addShape(later.copyWith(id: laterId)),
      );
      final leftoverDoc = parser.parse(
        writer.write(originalBytes: writer.emptyDocument(), edited: doc),
      );
      expect(
        glyphContaining(
          leftoverDoc.pages.first.findShapeById(omittedId)!,
          '<b>CD</b>',
        )!
            .text,
        '<b>CD</b>',
        reason: 'a second save keeps leftover omitted-format markup',
      );
      expect(
        runContaining(
          glyphContaining(
            leftoverDoc.pages.first.findShapeById(laterId)!,
            'CD',
          )!,
          'CD',
        )!
            .charStyle
            .style
            .bold,
        isTrue,
        reason: 'a second save keeps leftover format=html Style.bold',
      );
    },
  );

  test(
    'mxStencil fillstrokecolor omitted leftover keeps FillForegnd for LibreOffice',
    () {
      const red = VsdxColor(0xFFFF0000);
      const green = VsdxColor(0xFF00FF00);

      int countFill(VsdxShape shape, VsdxColor color) {
        var n = 0;
        void walk(VsdxShape next) {
          if (next.fill.pattern != 0 && next.fill.foreground == color) {
            n++;
          }
          for (final child in next.children) {
            walk(child);
          }
        }

        walk(shape);
        return n;
      }

      final omitted = decodeDrawioMxStencilXml(
        '<shape name="O" w="32" h="32" strokewidth="1">'
        '<foreground>'
        '<fillstrokecolor color="#ff0000"/>'
        '<rect x="0" y="0" w="10" h="10"/>'
        '<fillstroke/>'
        '<fillstrokecolor/>'
        '<rect x="12" y="12" w="10" h="10"/>'
        '<fillstroke/>'
        '</foreground>'
        '</shape>',
        id: 534,
      );
      expect(
        countFill(omitted, red),
        2,
        reason: 'omitted fillstrokecolor is NestedStencil skip / official '
            'no-op; leftover must keep the leftover hex Draw '
            'collectFillAndShadow paints (`tokens.txt` FillForegnd)',
      );

      final keep = decodeDrawioMxStencilXml(
        '<shape name="K" w="32" h="32" strokewidth="1">'
        '<foreground>'
        '<fillstrokecolor color="#ff0000"/>'
        '<rect x="0" y="0" w="10" h="10"/>'
        '<fillstroke/>'
        '<rect x="12" y="12" w="10" h="10"/>'
        '<fillstroke/>'
        '</foreground>'
        '</shape>',
      );
      expect(
        countFill(keep, red),
        2,
        reason: 'without an omitted fillstrokecolor leftover keeps hex',
      );

      final later = decodeDrawioMxStencilXml(
        '<shape name="L" w="32" h="32" strokewidth="1">'
        '<foreground>'
        '<rect x="0" y="0" w="10" h="10"/>'
        '<fillstroke/>'
        '<fillstrokecolor color="#ff0000"/>'
        '<rect x="12" y="12" w="10" h="10"/>'
        '<fillstroke/>'
        '</foreground>'
        '</shape>',
      );
      expect(
        countFill(later, red),
        1,
        reason: 'later fillstrokecolor leftover-bakes a red sibling so Draw '
            'does not paint both plates leftover hex',
      );

      final includeHost = decodeDrawioMxStencilXml(
        '<shapes name="mxgraph.test">'
        '<shape name="host" w="32" h="32" strokewidth="1">'
        '<foreground>'
        '<fillstrokecolor color="#00ff00"/>'
        '<rect x="0" y="0" w="8" h="8"/>'
        '<fillstroke/>'
        '<include-shape name="mxgraph.test.tile" x="10" y="10" w="16" h="16"/>'
        '</foreground>'
        '</shape>'
        '<shape name="tile" w="16" h="16" strokewidth="1">'
        '<foreground>'
        '<fillstrokecolor color="#ff0000"/>'
        '<fillstrokecolor/>'
        '<rect x="0" y="0" w="16" h="16"/>'
        '<fillstroke/>'
        '</foreground>'
        '</shape>'
        '</shapes>',
      );
      expect(countFill(includeHost, green), 1);
      expect(
        countFill(includeHost, red),
        1,
        reason: 'include-shape nested omitted fillstrokecolor leftover-bakes '
            'the nested hex so Draw does not inherit host green',
      );

      final writer = VsdxWriter();
      final parser = DocumentParser();
      var doc = parser.parse(writer.emptyDocument());
      final omittedId = doc.pages.first.nextFreeShapeId();
      doc = doc.replacePage(
        0,
        doc.pages.first.addShape(omitted.copyWith(id: omittedId)),
      );
      final laterId = doc.pages.first.nextFreeShapeId();
      doc = doc.replacePage(
        0,
        doc.pages.first.addShape(later.copyWith(id: laterId)),
      );
      final leftoverDoc = parser.parse(
        writer.write(originalBytes: writer.emptyDocument(), edited: doc),
      );
      expect(
        countFill(leftoverDoc.pages.first.findShapeById(omittedId)!, red),
        2,
        reason: 'a second save keeps leftover FillForegnd Draw paints',
      );
      expect(
        countFill(leftoverDoc.pages.first.findShapeById(laterId)!, red),
        1,
        reason: 'a second save keeps the later leftover hex sibling',
      );
    },
  );

