  test(
    'mxStencil html CSS padding percent omitted leftover IndLeft for LibreOffice',
    () {
      List<double> indents(VsdxShape shape) {
        final values = <double>[];
        void walk(VsdxShape next) {
          for (final run in next.richText.runs) {
            values.add(run.paraStyle.indentLeftInches);
          }
          for (final child in next.children) {
            walk(child);
          }
        }

        walk(shape);
        return values;
      }

      const canvasScale = 1.5 / 100;
      // NestedStencil htmlCssLength: 10% of text box w=80, not parseFloat
      // "10%" → 10px.
      final pad = 80 * 0.10 * canvasScale;
      const keepT =
          '<text str="&lt;p style=&quot;padding-left:10%&quot;&gt;AB&lt;/p&gt;" '
          'x="0" y="0" w="80" h="20" format="html" align="left" valign="top"/>';
