        [omitBox(), keepBox()],
        reason: 'a second save keeps the later leftover IndLeft/SpAfter sibling',
      );
    },
  );

  test(
    'mxStencil fillstrokecolor red omitted leftover FillForegnd for LibreOffice',
    () {
      int fillCount(VsdxShape shape) {
        var n = 0;
        void walk(VsdxShape next) {
          if (next.fill.hasFill) n++;
          for (final child in next.children) {
            walk(child);
          }
        }

        walk(shape);
        return n;
      }

      int lineCount(VsdxShape shape) {
        var n = 0;
        void walk(VsdxShape next) {
          if (next.line.hasLine) n++;
          for (final child in next.children) {
            walk(child);
          }
        }

        walk(shape);
        return n;
      }

