        '<shape name="O" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<fillstrokecolor color="pink"/>'
        '<rect x="0" y="0" w="40" h="10"/>'
        '<fillstroke/>'
        '<fillcolor/>'
        '<strokecolor/>'
        '<rect x="0" y="20" w="40" h="10"/>'
        '<fillstroke/>'
        '</foreground>'
        '</shape>',
        id: 988,
      );
