      const keepSecond =
          '<text str="&lt;p style=&quot;padding:16px 4px 8px&quot;&gt;CD&lt;/p&gt;" x="0" y="30" w="80" h="20" format="html" align="left" valign="top"/>';

      final omitted = decodeDrawioMxStencilXml(
        '<shape name="O" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '$keepT'
        '$omittedT'
        '</foreground>'
        '</shape>',
        id: 1211,
      );
      expect(
        boxes(omitted),
        [keepBox(), omitBox()],
        reason: 'omitted html CSS padding:16px 4px 8px is UA; leftover must not keep IndLeft/SpBefore/SpAfter '
            'so Draw collectParaIX does not inset the later glyph '
            '(`tokens.txt` Ind*/Sp* → fo:margin-left 0.152cm vs 0cm / fo:margin-top 1.029cm vs 0.419cm / fo:margin-bottom 0.724cm vs 0.419cm)',
      );

      final keep = decodeDrawioMxStencilXml(
