      final omitted = decodeDrawioMxStencilXml(
        '<shape name="O" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '$keepT'
        '$omittedT'
        '</foreground>'
        '</shape>',
        id: 1370,
      );
      expect(
        colors(omitted),
        [hexf72, black],
        reason: 'omitted html CSS color:#f72 is canvas black; leftover must not keep '
            'Char.Color so Draw collectCharIX does not tint the later glyph '
            '(`tokens.txt` Color → fo:color #ff7722)',
      );

      final keep = decodeDrawioMxStencilXml(
        '<shape name="K" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '$keepT'
        '$keepT2'
        '</foreground>'
