        '<foreground>'
        '$omittedT'
        '</foreground>'
        '</shape>'
        '</shapes>',
      );
      expect(
        sizes(keep),
        everyElement(closeTo(keepSize, 1e-9)),
        reason: 'without omitted html CSS 86rem leftover keeps Char.Size',
      );
      expect(
        sizes(later),
        [closeTo(omittedSize, 1e-9), closeTo(keepSize, 1e-9)],
        reason: 'later html CSS 86rem leftover-bakes a sibling Char.Size',
      );
      expect(
        sizes(includeHost),
        [closeTo(keepSize, 1e-9), closeTo(omittedSize, 1e-9)],
