  test(
    'mxStencil strokecolor aliceblue omitted leftover LineColor for LibreOffice',
    () {
      int lineCount(VsdxShape shape) {
        var n = 0;
        void walk(VsdxShape next) {
          if (next.line.hasLine) n++;
          for (final child in next.children) {
            walk(child);
          }
        }

        walk(shape);
        return n;
      }

      VsdxColor? strokedLc(VsdxShape shape) {
        VsdxColor? found;
        void walk(VsdxShape next) {
          if (next.line.hasLine) found = next.line.color;
          for (final child in next.children) {
            walk(child);
          }
        }

        walk(shape);
        return found;
      }

      final aliceblue = VsdxColor.tryParse('#f0f8ff')!;
