        '<foreground>'
        '<strokecolor color="aliceblue"/>'
        '<rect x="0" y="0" w="40" h="10"/>'
        '<stroke/>'
        '<strokecolor color="aliceblue"/>'
        '<rect x="0" y="20" w="40" h="10"/>'
        '<stroke/>'
