        colors(keep),
        everyElement(hexaa8),
        reason: 'without omitted html CSS color:#aa8 leftover keeps Char.Color',
      );
      expect(
        colors(later),
        [black, hexaa8],
        reason: 'later html CSS color:#aa8 leftover-bakes a sibling Char.Color',
      );
      expect(
        colors(includeHost),
        [hexaa8, black],
