  test(
    'mxStencil html CSS padding 2px 2px 8px omitted leftover Para for LibreOffice',
    () {
      List<List<double>> boxes(VsdxShape shape) {
        final values = <List<double>>[];
        void walk(VsdxShape next) {
          for (final run in next.richText.runs) {
            final p = run.paraStyle;
            values.add([
              p.indentLeftInches,
              p.indentRightInches,
              p.spaceBeforeInches,
              p.spaceAfterInches,
            ]);
          }
          for (final child in next.children) {
            walk(child);
          }
        }

        walk(shape);
        return values;
      }

      const canvasScale = 1.5 / 100;
      final pad = 8 * canvasScale;
      final padX = 16 * canvasScale;
      final padB = 4 * canvasScale;
      final padL = 2 * canvasScale;
      final ua = 11 * canvasScale;
      List<Matcher> keepBox() => [
            closeTo(padL, 1e-9),
            closeTo(padL, 1e-9),
            closeTo(padL + ua, 1e-9),
            closeTo(pad + ua, 1e-9),
          ];
      List<Matcher> omitBox() => [
            closeTo(0, 1e-9),
            closeTo(0, 1e-9),
            closeTo(ua, 1e-9),
            closeTo(ua, 1e-9),
          ];
      const keepT =
          '<text str="&lt;p style=&quot;padding:2px 2px 8px&quot;&gt;AB&lt;/p&gt;" x="0" y="0" w="80" h="20" format="html" align="left" valign="top"/>';
