      final omitted = decodeDrawioMxStencilXml(
        '<shape name="O" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '$keepT'
        '$omittedT'
        '</foreground>'
        '</shape>',
        id: 1915,
      );
      expect(
        boxes(omitted),
        [keepBox(), omitBox()],
        reason: 'omitted html CSS padding:2px 2px 8px is UA; leftover must not keep IndLeft/SpBefore/SpAfter '
            'so Draw collectParaIX does not inset the later glyph '
            '(`tokens.txt` Ind*/Sp* → fo:margin-left 0.076cm vs 0cm / fo:margin-top 0.495cm vs 0.419cm / fo:margin-bottom 0.724cm vs 0.419cm)',
