      const keepT2 =
          '<text str="&lt;p style=&quot;margin:3px 3px 3px&quot;&gt;CD&lt;/p&gt;" x="0" y="30" w="80" h="20" format="html" align="left" valign="top"/>';
      const omittedFirst =
