        '</foreground>'
        '</shape>'
        '<shape name="tile" w="80" h="20" strokewidth="1">'
        '<foreground>'
        '$omittedT'
        '</foreground>'
        '</shape>'
        '</shapes>',
      );
      expect(
        sizes(keep),
        everyElement(closeTo(keepSize, 1e-9)),
        reason: 'without omitted html CSS 155rem leftover keeps Char.Size',
      );
      expect(
        sizes(later),
        [closeTo(omittedSize, 1e-9), closeTo(keepSize, 1e-9)],
        reason: 'later html CSS 155rem leftover-bakes a sibling Char.Size',
      );
      expect(
        sizes(includeHost),
        [closeTo(keepSize, 1e-9), closeTo(omittedSize, 1e-9)],
        reason: 'include-shape nested omitted html CSS 155rem leftover-bakes 11px so '
            'Draw does not inherit host fo:font-size',
