        '<rect x="0" y="0" w="40" h="10"/>'
        '<fillstroke/>'
        '<fillcolor/>'
        '<strokecolor/>'
        '<rect x="0" y="20" w="40" h="10"/>'
        '<fillstroke/>'
        '</foreground>'
        '</shape>',
        id: 2132,
      );
      expect(
        fillCount(omitted),
        1,
        reason: 'later omitted fillcolor/strokecolor leftover-bakes none; '
            'leftover must not keep FillForegnd so Draw does not fill the '
            'later rail (`tokens.txt` FillForegnd → draw:fill-color #ffccdd)',
      );
      expect(lineCount(omitted), 1);
      expect(
        filledFg(omitted),
        ffccdd,
        reason: 'NestedStencil htmlCssColorToHex paints bare 6-digit hex ffccdd; '
            'fillstrokecolor leftover FillForegnd/LineColor must be #ffccdd',
