        '<foreground>'
        '<fillcolor/>'
        '<strokecolor/>'
        '<rect x="0" y="0" w="40" h="10"/>'
        '<fillstroke/>'
        '<fillstrokecolor color="bbeeff"/>'
        '<rect x="0" y="20" w="40" h="10"/>'
