      expect(
        filledFg(omitted),
        ee1122,
        reason: 'NestedStencil htmlCssColorToHex paints bare 6-digit hex ee1122; '
            'fillstrokecolor leftover FillForegnd/LineColor must be #ee1122',
      );

      final keep = decodeDrawioMxStencilXml(
