        colors(keep),
        everyElement(hexb1d),
        reason: 'without omitted html CSS color:#b1d leftover keeps Char.Color',
      );
      expect(
        colors(later),
        [black, hexb1d],
        reason: 'later html CSS color:#b1d leftover-bakes a sibling Char.Color',
      );
      expect(
        colors(includeHost),
        [hexb1d, black],
