        reason: 'without omitted html CSS margin:8px 3px 2px leftover keeps Ind*/Sp*',
      );
      expect(
        boxes(later),
        [omitBox(), keepBox()],
        reason: 'later html CSS margin:8px 3px 2px leftover-bakes a sibling Ind*/Sp*',
      );
      expect(
