        colors(keep),
        everyElement(hexb9b),
        reason: 'without omitted html CSS color:#b9b leftover keeps Char.Color',
      );
      expect(
        colors(later),
        [black, hexb9b],
        reason: 'later html CSS color:#b9b leftover-bakes a sibling Char.Color',
      );
      expect(
        colors(includeHost),
        [hexb9b, black],
