  test(
    'mxStencil strokecolor cccc8b omitted leftover LineColor for LibreOffice',
    () {
      int lineCount(VsdxShape shape) {
        var n = 0;
        void walk(VsdxShape next) {
          if (next.line.hasLine) n++;
          for (final child in next.children) {
            walk(child);
          }
        }

        walk(shape);
        return n;
      }

      VsdxColor? strokedLc(VsdxShape shape) {
        VsdxColor? found;
        void walk(VsdxShape next) {
          if (next.line.hasLine) found = next.line.color;
          for (final child in next.children) {
            walk(child);
          }
        }

        walk(shape);
        return found;
      }

      final cccc8b = VsdxColor.tryParse('#cccc8b')!;
      final omitted = decodeDrawioMxStencilXml(
        '<shape name="O" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<strokecolor color="cccc8b"/>'
        '<rect x="0" y="0" w="40" h="10"/>'
        '<stroke/>'
        '<strokecolor/>'
        '<rect x="0" y="20" w="40" h="10"/>'
        '<stroke/>'
        '</foreground>'
        '</shape>',
        id: 2966,
      );
      expect(
        lineCount(omitted),
        1,
        reason: 'omitted strokecolor is setStrokeColor(null)/none; leftover '
            'must not keep LineColor so Draw collectLine does not stroke the '
            'later rail (`tokens.txt` LineColor → svg:stroke-color #cccc8b)',
      );
      expect(
        strokedLc(omitted),
        cccc8b,
        reason: 'NestedStencil htmlCssColorToHex paints bare 6-digit hex cccc8b; leftover '
            'LineColor must be #cccc8b so Draw paints the keep rail',
      );

      final keep = decodeDrawioMxStencilXml(
        '<shape name="K" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<strokecolor color="cccc8b"/>'
        '<rect x="0" y="0" w="40" h="10"/>'
        '<stroke/>'
        '<strokecolor color="cccc8b"/>'
        '<rect x="0" y="20" w="40" h="10"/>'
        '<stroke/>'
        '</foreground>'
        '</shape>',
      );
      final later = decodeDrawioMxStencilXml(
        '<shape name="L" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<strokecolor/>'
        '<rect x="0" y="0" w="40" h="10"/>'
        '<stroke/>'
        '<strokecolor color="cccc8b"/>'
        '<rect x="0" y="20" w="40" h="10"/>'
        '<stroke/>'
        '</foreground>'
        '</shape>',
      );
      final includeHost = decodeDrawioMxStencilXml(
        '<shapes name="mxgraph.test">'
        '<shape name="host" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<strokecolor color="cccc8b"/>'
        '<rect x="0" y="0" w="10" h="10"/>'
        '<stroke/>'
        '<include-shape name="mxgraph.test.tile" x="20" y="0" w="10" h="10"/>'
        '</foreground>'
        '</shape>'
        '<shape name="tile" w="10" h="10" strokewidth="1">'
        '<foreground>'
        '<strokecolor/>'
        '<rect x="0" y="0" w="10" h="10"/>'
        '<stroke/>'
        '</foreground>'
        '</shape>'
        '</shapes>',
      );
      expect(
        lineCount(keep),
        2,
        reason: 'without omitted strokecolor leftover keeps cccc8b LineColor',
      );
      expect(lineCount(later), 1);
      expect(strokedLc(later), cccc8b);
      expect(
        lineCount(includeHost),
        1,
        reason: 'include-shape nested omitted strokecolor leftover-bakes none '
            'so Draw does not inherit host svg:stroke-color',
      );

      final writer = VsdxWriter();
      final parser = DocumentParser();
      var doc = parser.parse(writer.emptyDocument());
      final omittedId = doc.pages.first.nextFreeShapeId();
      doc = doc.replacePage(
        0,
        doc.pages.first.addShape(omitted.copyWith(id: omittedId)),
      );
      final laterId = doc.pages.first.nextFreeShapeId();
      doc = doc.replacePage(
        0,
        doc.pages.first.addShape(later.copyWith(id: laterId)),
      );
      final leftoverDoc = parser.parse(
        writer.write(originalBytes: writer.emptyDocument(), edited: doc),
      );
      expect(
        lineCount(leftoverDoc.pages.first.findShapeById(omittedId)!),
        1,
        reason: 'a second save keeps leftover cccc8b LineColor Draw paints',
      );
      expect(
        strokedLc(leftoverDoc.pages.first.findShapeById(omittedId)!),
        cccc8b,
      );
      expect(
        lineCount(leftoverDoc.pages.first.findShapeById(laterId)!),
        1,
        reason: 'a second save keeps the later leftover LineColor sibling',
      );
    },
  );

  test(
    'mxStencil html CSS font-size 269rem omitted leftover Char.Size for LibreOffice',
    () {
      List<double> sizes(VsdxShape shape) {
        final values = <double>[];
        void walk(VsdxShape next) {
          for (final run in next.richText.runs) {
            values.add(run.charStyle.fontSizeInches);
          }
          for (final child in next.children) {
            walk(child);
          }
        }

        walk(shape);
        return values;
      }

      const canvasScale = 1.5 / 100;
      final keepSize = 269 * 16 * canvasScale;
      final omittedSize = 11 * canvasScale;
      const keepT =
          '<text str="&lt;span style=&quot;font-size:269rem&quot;&gt;AB&lt;/span&gt;" x="0" y="0" w="80" h="20" format="html" align="left" valign="top"/>';
      const omittedT =
          '<text str="&lt;span&gt;CD&lt;/span&gt;" x="0" y="30" w="80" h="20" format="html" align="left" valign="top"/>';
      const keepT2 =
          '<text str="&lt;span style=&quot;font-size:269rem&quot;&gt;CD&lt;/span&gt;" x="0" y="30" w="80" h="20" format="html" align="left" valign="top"/>';
      const omittedFirst =
          '<text str="&lt;span&gt;AB&lt;/span&gt;" x="0" y="0" w="80" h="20" format="html" align="left" valign="top"/>';
      const keepSecond =
          '<text str="&lt;span style=&quot;font-size:269rem&quot;&gt;CD&lt;/span&gt;" x="0" y="30" w="80" h="20" format="html" align="left" valign="top"/>';

      final omitted = decodeDrawioMxStencilXml(
        '<shape name="O" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '$keepT'
        '$omittedT'
        '</foreground>'
        '</shape>',
        id: 2967,
      );
      expect(
        sizes(omitted),
        [closeTo(keepSize, 1e-9), closeTo(omittedSize, 1e-9)],
        reason: 'omitted html CSS 269rem is canvas 11px; leftover must not keep '
            'Char.Size so Draw collectCharIX does not change the later glyph '
            '(`tokens.txt` Size → fo:font-size 4648.3pt vs 11.9pt)',
      );

      final keep = decodeDrawioMxStencilXml(
        '<shape name="K" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '$keepT'
        '$keepT2'
        '</foreground>'
        '</shape>',
      );
      final later = decodeDrawioMxStencilXml(
        '<shape name="L" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '$omittedFirst'
        '$keepSecond'
        '</foreground>'
        '</shape>',
      );
      final includeHost = decodeDrawioMxStencilXml(
        '<shapes name="mxgraph.test">'
        '<shape name="host" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '$keepT'
        '<include-shape name="mxgraph.test.tile" x="0" y="30" w="80" h="20"/>'
        '</foreground>'
        '</shape>'
        '<shape name="tile" w="80" h="20" strokewidth="1">'
        '<foreground>'
        '$omittedT'
        '</foreground>'
        '</shape>'
        '</shapes>',
      );
      expect(
        sizes(keep),
        everyElement(closeTo(keepSize, 1e-9)),
        reason: 'without omitted html CSS 269rem leftover keeps Char.Size',
      );
      expect(
        sizes(later),
        [closeTo(omittedSize, 1e-9), closeTo(keepSize, 1e-9)],
        reason: 'later html CSS 269rem leftover-bakes a sibling Char.Size',
      );
      expect(
        sizes(includeHost),
        [closeTo(keepSize, 1e-9), closeTo(omittedSize, 1e-9)],
        reason: 'include-shape nested omitted html CSS 269rem leftover-bakes 11px so '
            'Draw does not inherit host fo:font-size',
      );

      final writer = VsdxWriter();
      final parser = DocumentParser();
      var doc = parser.parse(writer.emptyDocument());
      final omittedId = doc.pages.first.nextFreeShapeId();
      doc = doc.replacePage(
        0,
        doc.pages.first.addShape(omitted.copyWith(id: omittedId)),
      );
      final laterId = doc.pages.first.nextFreeShapeId();
      doc = doc.replacePage(
        0,
        doc.pages.first.addShape(later.copyWith(id: laterId)),
      );
      final leftoverDoc = parser.parse(
        writer.write(originalBytes: writer.emptyDocument(), edited: doc),
      );
      expect(
        sizes(leftoverDoc.pages.first.findShapeById(omittedId)!),
        [closeTo(keepSize, 1e-9), closeTo(omittedSize, 1e-9)],
        reason: 'a second save keeps leftover Char.Size Draw paints',
      );
      expect(
        sizes(leftoverDoc.pages.first.findShapeById(laterId)!),
        [closeTo(omittedSize, 1e-9), closeTo(keepSize, 1e-9)],
        reason: 'a second save keeps the later leftover Char.Size sibling',
      );
    },
  );

