  test(
    'mxStencil html CSS font-size 270rem omitted leftover Char.Size for LibreOffice',
    () {
      List<double> sizes(VsdxShape shape) {
        final values = <double>[];
        void walk(VsdxShape next) {
          for (final run in next.richText.runs) {
            values.add(run.charStyle.fontSizeInches);
          }
          for (final child in next.children) {
            walk(child);
          }
        }

        walk(shape);
        return values;
      }

      const canvasScale = 1.5 / 100;
      final keepSize = 270 * 16 * canvasScale;
      final omittedSize = 11 * canvasScale;
      const keepT =
          '<text str="&lt;span style=&quot;font-size:270rem&quot;&gt;AB&lt;/span&gt;" x="0" y="0" w="80" h="20" format="html" align="left" valign="top"/>';
      const omittedT =
          '<text str="&lt;span&gt;CD&lt;/span&gt;" x="0" y="30" w="80" h="20" format="html" align="left" valign="top"/>';
      const keepT2 =
          '<text str="&lt;span style=&quot;font-size:270rem&quot;&gt;CD&lt;/span&gt;" x="0" y="30" w="80" h="20" format="html" align="left" valign="top"/>';
      const omittedFirst =
          '<text str="&lt;span&gt;AB&lt;/span&gt;" x="0" y="0" w="80" h="20" format="html" align="left" valign="top"/>';
      const keepSecond =
          '<text str="&lt;span style=&quot;font-size:270rem&quot;&gt;CD&lt;/span&gt;" x="0" y="30" w="80" h="20" format="html" align="left" valign="top"/>';

      final omitted = decodeDrawioMxStencilXml(
        '<shape name="O" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '$keepT'
        '$omittedT'
        '</foreground>'
        '</shape>',
        id: 2975,
      );
      expect(
        sizes(omitted),
        [closeTo(keepSize, 1e-9), closeTo(omittedSize, 1e-9)],
        reason: 'omitted html CSS 270rem is canvas 11px; leftover must not keep '
            'Char.Size so Draw collectCharIX does not change the later glyph '
            '(`tokens.txt` Size → fo:font-size 4665.6pt vs 11.9pt)',
      );

      final keep = decodeDrawioMxStencilXml(
        '<shape name="K" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '$keepT'
        '$keepT2'
