      const omittedT =
          '<text str="&lt;span&gt;CD&lt;/span&gt;" x="0" y="30" w="80" h="20" format="html" align="left" valign="top"/>';
      const keepT2 =
          '<text str="&lt;span style=&quot;color:#e03&quot;&gt;CD&lt;/span&gt;" x="0" y="30" w="80" h="20" format="html" align="left" valign="top"/>';
      const omittedFirst =
          '<text str="&lt;span&gt;AB&lt;/span&gt;" x="0" y="0" w="80" h="20" format="html" align="left" valign="top"/>';
      const keepSecond =
          '<text str="&lt;span style=&quot;color:#e03&quot;&gt;CD&lt;/span&gt;" x="0" y="30" w="80" h="20" format="html" align="left" valign="top"/>';

      final omitted = decodeDrawioMxStencilXml(
        '<shape name="O" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '$keepT'
        '$omittedT'
        '</foreground>'
        '</shape>',
        id: 2986,
      );
      expect(
        colors(omitted),
        [hexe03, black],
        reason: 'omitted html CSS color:#e03 is canvas black; leftover must not keep '
            'Char.Color so Draw collectCharIX does not tint the later glyph '
            '(`tokens.txt` Color → fo:color #ee0033)',
