      const keepSecond =
          '<text str="&lt;p style=&quot;padding:3px 1px 4px&quot;&gt;CD&lt;/p&gt;" x="0" y="30" w="80" h="20" format="html" align="left" valign="top"/>';

      final omitted = decodeDrawioMxStencilXml(
