        void walk(VsdxShape next) {
          if (next.fill.hasFill) found = next.fill.foreground;
          for (final child in next.children) {
            walk(child);
          }
        }

        walk(shape);
        return found;
      }

      final bbbb1e = VsdxColor.tryParse('#bbbb1e')!;
      final omitted = decodeDrawioMxStencilXml(
        '<shape name="O" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<fillcolor color="bbbb1e"/>'
        '<rect x="0" y="0" w="40" h="10"/>'
        '<fillstroke/>'
        '<fillcolor/>'
        '<rect x="0" y="20" w="40" h="10"/>'
        '<fillstroke/>'
        '</foreground>'
        '</shape>',
        id: 3293,
      );
      expect(
        fillCount(omitted),
        1,
        reason: 'omitted fillcolor is setFillColor(null)/none; leftover must '
            'not keep FillForegnd so Draw collectFillAndShadow does not fill '
            'the later rail (`tokens.txt` FillForegnd → draw:fill-color '
            '#bbbb1e)',
      );
      expect(
        filledFg(omitted),
        bbbb1e,
        reason: 'NestedStencil htmlCssColorToHex paints bare 6-digit hex bbbb1e; leftover '
            'FillForegnd must be #bbbb1e so Draw paints the keep rail',
      );

      final keep = decodeDrawioMxStencilXml(
        '<shape name="K" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<fillcolor color="bbbb1e"/>'
        '<rect x="0" y="0" w="40" h="10"/>'
        '<fillstroke/>'
        '<fillcolor color="bbbb1e"/>'
        '<rect x="0" y="20" w="40" h="10"/>'
        '<fillstroke/>'
        '</foreground>'
        '</shape>',
      );
      final later = decodeDrawioMxStencilXml(
        '<shape name="L" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<fillcolor/>'
        '<rect x="0" y="0" w="40" h="10"/>'
        '<fillstroke/>'
        '<fillcolor color="bbbb1e"/>'
        '<rect x="0" y="20" w="40" h="10"/>'
        '<fillstroke/>'
        '</foreground>'
        '</shape>',
      );
      final includeHost = decodeDrawioMxStencilXml(
        '<shapes name="mxgraph.test">'
        '<shape name="host" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<fillcolor color="bbbb1e"/>'
        '<rect x="0" y="0" w="10" h="10"/>'
        '<fillstroke/>'
        '<include-shape name="mxgraph.test.tile" x="20" y="0" w="10" h="10"/>'
        '</foreground>'
        '</shape>'
        '<shape name="tile" w="10" h="10" strokewidth="1">'
        '<foreground>'
        '<fillcolor/>'
        '<rect x="0" y="0" w="10" h="10"/>'
        '<fillstroke/>'
        '</foreground>'
        '</shape>'
        '</shapes>',
      );
      expect(
        fillCount(keep),
        2,
        reason: 'without omitted fillcolor leftover keeps bbbb1e FillForegnd',
      );
      expect(filledFg(later), bbbb1e);
      expect(fillCount(later), 1);
      expect(
        fillCount(includeHost),
        1,
        reason: 'include-shape nested omitted fillcolor leftover-bakes none so '
            'Draw does not inherit host draw:fill-color',
      );

      final writer = VsdxWriter();
