        void walk(VsdxShape next) {
          for (final run in next.richText.runs) {
            values.add(run.charStyle.color);
          }
          for (final child in next.children) {
            walk(child);
          }
        }

        walk(shape);
        return values;
      }

      final hexb88 = VsdxColor.tryParse('#bb8888')!;
      final black = VsdxColor.tryParse('#000000')!;
      const keepT =
          '<text str="&lt;span style=&quot;color:#b88&quot;&gt;AB&lt;/span&gt;" x="0" y="0" w="80" h="20" format="html" align="left" valign="top"/>';
      const omittedT =
          '<text str="&lt;span&gt;CD&lt;/span&gt;" x="0" y="30" w="80" h="20" format="html" align="left" valign="top"/>';
      const keepT2 =
          '<text str="&lt;span style=&quot;color:#b88&quot;&gt;CD&lt;/span&gt;" x="0" y="30" w="80" h="20" format="html" align="left" valign="top"/>';
      const omittedFirst =
          '<text str="&lt;span&gt;AB&lt;/span&gt;" x="0" y="0" w="80" h="20" format="html" align="left" valign="top"/>';
      const keepSecond =
          '<text str="&lt;span style=&quot;color:#b88&quot;&gt;CD&lt;/span&gt;" x="0" y="30" w="80" h="20" format="html" align="left" valign="top"/>';

      final omitted = decodeDrawioMxStencilXml(
        '<shape name="O" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '$keepT'
        '$omittedT'
        '</foreground>'
        '</shape>',
        id: 3298,
      );
      expect(
        colors(omitted),
        [hexb88, black],
        reason: 'omitted html CSS color:#b88 is canvas black; leftover must not keep '
            'Char.Color so Draw collectCharIX does not tint the later glyph '
            '(`tokens.txt` Color → fo:color #bb8888)',
      );

      final keep = decodeDrawioMxStencilXml(
        '<shape name="K" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '$keepT'
        '$keepT2'
        '</foreground>'
        '</shape>',
      );
      final later = decodeDrawioMxStencilXml(
        '<shape name="L" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '$omittedFirst'
        '$keepSecond'
        '</foreground>'
        '</shape>',
      );
      final includeHost = decodeDrawioMxStencilXml(
        '<shapes name="mxgraph.test">'
        '<shape name="host" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '$keepT'
        '<include-shape name="mxgraph.test.tile" x="0" y="30" w="80" h="20"/>'
        '</foreground>'
        '</shape>'
        '<shape name="tile" w="80" h="20" strokewidth="1">'
        '<foreground>'
        '$omittedT'
        '</foreground>'
        '</shape>'
        '</shapes>',
      );
      expect(
        colors(keep),
        everyElement(hexb88),
        reason: 'without omitted html CSS color:#b88 leftover keeps Char.Color',
      );
      expect(
        colors(later),
        [black, hexb88],
        reason: 'later html CSS color:#b88 leftover-bakes a sibling Char.Color',
      );
      expect(
        colors(includeHost),
        [hexb88, black],
        reason: 'include-shape nested omitted html CSS color:#b88 leftover-bakes black '
            'so Draw does not inherit host fo:color',
      );

      final writer = VsdxWriter();
      final parser = DocumentParser();
      var doc = parser.parse(writer.emptyDocument());
      final omittedId = doc.pages.first.nextFreeShapeId();
      doc = doc.replacePage(
        0,
        doc.pages.first.addShape(omitted.copyWith(id: omittedId)),
      );
      final laterId = doc.pages.first.nextFreeShapeId();
      doc = doc.replacePage(
        0,
        doc.pages.first.addShape(later.copyWith(id: laterId)),
      );
      final leftoverDoc = parser.parse(
        writer.write(originalBytes: writer.emptyDocument(), edited: doc),
      );
      expect(
        colors(leftoverDoc.pages.first.findShapeById(omittedId)!),
        [hexb88, black],
        reason: 'a second save keeps leftover Char.Color Draw paints',
      );
      expect(
        colors(leftoverDoc.pages.first.findShapeById(laterId)!),
        [black, hexb88],
        reason: 'a second save keeps the later leftover Char.Color sibling',
      );
    },
  );

  test(
    'mxStencil html CSS margin 3px 5px 2px omitted leftover Para for LibreOffice',
    () {
      List<List<double>> boxes(VsdxShape shape) {
        final values = <List<double>>[];
        void walk(VsdxShape next) {
          for (final run in next.richText.runs) {
            final p = run.paraStyle;
            values.add([
              p.indentLeftInches,
              p.indentRightInches,
              p.spaceBeforeInches,
              p.spaceAfterInches,
            ]);
          }
          for (final child in next.children) {
            walk(child);
          }
        }

        walk(shape);
        return values;
      }

      const canvasScale = 1.5 / 100;
      final pad = 8 * canvasScale;
      final padX = 16 * canvasScale;
      final padB = 4 * canvasScale;
      final padL = 2 * canvasScale;
      final ua = 11 * canvasScale;
      List<Matcher> keepBox() => [
            closeTo(5 * canvasScale, 1e-9),
            closeTo(5 * canvasScale, 1e-9),
            closeTo(3 * canvasScale, 1e-9),
            closeTo(padL, 1e-9),
          ];
      List<Matcher> omitBox() => [
            closeTo(0, 1e-9),
            closeTo(0, 1e-9),
            closeTo(ua, 1e-9),
            closeTo(ua, 1e-9),
          ];
      const keepT =
          '<text str="&lt;p style=&quot;margin:3px 5px 2px&quot;&gt;AB&lt;/p&gt;" x="0" y="0" w="80" h="20" format="html" align="left" valign="top"/>';
      const omittedT =
          '<text str="&lt;p&gt;CD&lt;/p&gt;" x="0" y="30" w="80" h="20" format="html" align="left" valign="top"/>';
      const keepT2 =
          '<text str="&lt;p style=&quot;margin:3px 5px 2px&quot;&gt;CD&lt;/p&gt;" x="0" y="30" w="80" h="20" format="html" align="left" valign="top"/>';
      const omittedFirst =
          '<text str="&lt;p&gt;AB&lt;/p&gt;" x="0" y="0" w="80" h="20" format="html" align="left" valign="top"/>';
      const keepSecond =
          '<text str="&lt;p style=&quot;margin:3px 5px 2px&quot;&gt;CD&lt;/p&gt;" x="0" y="30" w="80" h="20" format="html" align="left" valign="top"/>';

      final omitted = decodeDrawioMxStencilXml(
        '<shape name="O" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '$keepT'
        '$omittedT'
        '</foreground>'
        '</shape>',
        id: 3299,
      );
      expect(
        boxes(omitted),
        [keepBox(), omitBox()],
        reason: 'omitted html CSS margin:3px 5px 2px is UA; leftover must not keep IndLeft/SpBefore/SpAfter '
            'so Draw collectParaIX does not inset the later glyph '
            '(`tokens.txt` Ind*/Sp* → fo:margin-left 0.191cm vs 0cm / fo:margin-top 0.114cm vs 0.419cm / fo:margin-bottom 0.076cm vs 0.419cm)',
      );

      final keep = decodeDrawioMxStencilXml(
        '<shape name="K" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '$keepT'
        '$keepT2'
        '</foreground>'
        '</shape>',
      );
      final later = decodeDrawioMxStencilXml(
        '<shape name="L" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '$omittedFirst'
        '$keepSecond'
        '</foreground>'
        '</shape>',
      );
      final includeHost = decodeDrawioMxStencilXml(
        '<shapes name="mxgraph.test">'
        '<shape name="host" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '$keepT'
        '<include-shape name="mxgraph.test.tile" x="0" y="30" w="80" h="20"/>'
        '</foreground>'
        '</shape>'
        '<shape name="tile" w="80" h="20" strokewidth="1">'
        '<foreground>'
        '$omittedT'
        '</foreground>'
        '</shape>'
        '</shapes>',
      );
      expect(
        boxes(keep),
        [keepBox(), keepBox()],
        reason: 'without omitted html CSS margin:3px 5px 2px leftover keeps Ind*/Sp*',
      );
      expect(
        boxes(later),
        [omitBox(), keepBox()],
        reason: 'later html CSS margin:3px 5px 2px leftover-bakes a sibling Ind*/Sp*',
      );
      expect(
        boxes(includeHost),
        [keepBox(), omitBox()],
        reason: 'include-shape nested omitted html CSS margin:3px 5px 2px leftover-bakes UA so '
            'Draw does not inherit host fo:margin-*',
      );

      final writer = VsdxWriter();
      final parser = DocumentParser();
      var doc = parser.parse(writer.emptyDocument());
      final omittedId = doc.pages.first.nextFreeShapeId();
      doc = doc.replacePage(
        0,
        doc.pages.first.addShape(omitted.copyWith(id: omittedId)),
      );
      final laterId = doc.pages.first.nextFreeShapeId();
      doc = doc.replacePage(
        0,
        doc.pages.first.addShape(later.copyWith(id: laterId)),
      );
      final leftoverDoc = parser.parse(
        writer.write(originalBytes: writer.emptyDocument(), edited: doc),
      );
      expect(
        boxes(leftoverDoc.pages.first.findShapeById(omittedId)!),
        [keepBox(), omitBox()],
        reason: 'a second save keeps leftover IndLeft/SpBefore/SpAfter Draw paints',
      );
      expect(
        boxes(leftoverDoc.pages.first.findShapeById(laterId)!),
        [omitBox(), keepBox()],
        reason: 'a second save keeps the later leftover IndLeft/SpBefore/SpAfter sibling',
      );
    },
  );

