      final omittedSize = 11 * canvasScale;
      const keepT =
          '<text str="&lt;span style=&quot;font-size:329rem&quot;&gt;AB&lt;/span&gt;" x="0" y="0" w="80" h="20" format="html" align="left" valign="top"/>';
      const omittedT =
          '<text str="&lt;span&gt;CD&lt;/span&gt;" x="0" y="30" w="80" h="20" format="html" align="left" valign="top"/>';
      const keepT2 =
          '<text str="&lt;span style=&quot;font-size:329rem&quot;&gt;CD&lt;/span&gt;" x="0" y="30" w="80" h="20" format="html" align="left" valign="top"/>';
      const omittedFirst =
          '<text str="&lt;span&gt;AB&lt;/span&gt;" x="0" y="0" w="80" h="20" format="html" align="left" valign="top"/>';
      const keepSecond =
          '<text str="&lt;span style=&quot;font-size:329rem&quot;&gt;CD&lt;/span&gt;" x="0" y="30" w="80" h="20" format="html" align="left" valign="top"/>';

      final omitted = decodeDrawioMxStencilXml(
        '<shape name="O" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '$keepT'
        '$omittedT'
        '</foreground>'
        '</shape>',
        id: 3447,
      );
      expect(
        sizes(omitted),
        [closeTo(keepSize, 1e-9), closeTo(omittedSize, 1e-9)],
        reason: 'omitted html CSS 329rem is canvas 11px; leftover must not keep '
            'Char.Size so Draw collectCharIX does not change the later glyph '
            '(`tokens.txt` Size → fo:font-size 5685.1pt vs 11.9pt)',
      );

      final keep = decodeDrawioMxStencilXml(
        '<shape name="K" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '$keepT'
        '$keepT2'
        '</foreground>'
        '</shape>',
      );
      final later = decodeDrawioMxStencilXml(
        '<shape name="L" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '$omittedFirst'
        '$keepSecond'
        '</foreground>'
        '</shape>',
      );
      final includeHost = decodeDrawioMxStencilXml(
        '<shapes name="mxgraph.test">'
        '<shape name="host" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '$keepT'
        '<include-shape name="mxgraph.test.tile" x="0" y="30" w="80" h="20"/>'
        '</foreground>'
        '</shape>'
        '<shape name="tile" w="80" h="20" strokewidth="1">'
        '<foreground>'
        '$omittedT'
        '</foreground>'
        '</shape>'
        '</shapes>',
      );
      expect(
        sizes(keep),
        everyElement(closeTo(keepSize, 1e-9)),
        reason: 'without omitted html CSS 329rem leftover keeps Char.Size',
      );
      expect(
        sizes(later),
        [closeTo(omittedSize, 1e-9), closeTo(keepSize, 1e-9)],
        reason: 'later html CSS 329rem leftover-bakes a sibling Char.Size',
      );
      expect(
        sizes(includeHost),
        [closeTo(keepSize, 1e-9), closeTo(omittedSize, 1e-9)],
        reason: 'include-shape nested omitted html CSS 329rem leftover-bakes 11px so '
            'Draw does not inherit host fo:font-size',
