  test(
    'mxStencil mxXmlCanvas2D strokealpha omitted leftover bakes LineColorTrans 1 for LibreOffice',
    () {
      List<double> strokeTrans(VsdxShape shape) {
        final values = <double>[];
        void walk(VsdxShape next) {
          if (next.line.hasLine) values.add(next.line.transparency);
          for (final child in next.children) {
            walk(child);
          }
        }

        walk(shape);
        values.sort();
        return values;
      }

      bool hasStrokeTrans(VsdxShape shape, double trans) {
        if (shape.line.hasLine &&
            (shape.line.transparency - trans).abs() < 0.05) {
          return true;
        }
        return shape.children.any((child) => hasStrokeTrans(child, trans));
      }

      ({int fadedFill, int opaqueLine}) leftoverPaint(VsdxShape shape) {
        var fadedFill = 0;
        var opaqueLine = 0;
        void walk(VsdxShape next) {
          if (next.fill.hasFill && next.fill.foregroundTransparency > 0.5) {
            fadedFill++;
          }
          if (next.line.hasLine && next.line.transparency < 0.1) {
            opaqueLine++;
          }
          for (final child in next.children) {
            walk(child);
          }
        }

        walk(shape);
        return (fadedFill: fadedFill, opaqueLine: opaqueLine);
      }

      final omitted = decodeDrawioMxStencilXml(
        '<shape name="O" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<strokealpha/>'
        '<rect x="0" y="0" w="40" h="10"/>'
        '<stroke/>'
        '</foreground>'
        '</shape>',
        id: 517,
      );
      expect(
        strokeTrans(omitted).single,
        closeTo(1, 0.05),
        reason: 'omitted strokealpha is Number(null)=0; leftover fallback 1 '
            'kept LineColorTrans 0 so Draw collectLine painted an opaque '
            'rail (`tokens.txt` has no LineColorTrans)',
      );

      final keep = decodeDrawioMxStencilXml(
        '<shape name="K" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<rect x="0" y="0" w="40" h="10"/>'
        '<stroke/>'
        '</foreground>'
        '</shape>',
      );
      expect(
        strokeTrans(keep).single,
        closeTo(0, 0.05),
        reason: 'without a strokealpha node leftover keeps createState '
            'opaque LineColorTrans',
      );

      final laterHost = decodeDrawioMxStencilXml(
        '<shape name="L" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<rect x="0" y="0" w="40" h="10"/>'
        '<stroke/>'
        '<strokealpha/>'
        '<rect x="0" y="20" w="40" h="10"/>'
        '<stroke/>'
        '</foreground>'
        '</shape>',
      );
      expect(
        strokeTrans(laterHost),
        [closeTo(0, 0.05), closeTo(1, 0.05)],
        reason: 'later omitted strokealpha leftover-bakes LineColorTrans 1 '
            'so Draw does not paint the second rail opaque (`tokens.txt` '
            'has no LineColorTrans)',
      );

      final includeHost = decodeDrawioMxStencilXml(
        '<shapes name="mxgraph.test">'
        '<shape name="host" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<rect x="0" y="0" w="40" h="10"/>'
        '<stroke/>'
        '<include-shape name="mxgraph.test.tile" x="0" y="20" w="40" h="10"/>'
        '</foreground>'
        '</shape>'
        '<shape name="tile" w="40" h="10" strokewidth="1">'
        '<foreground>'
        '<strokealpha/>'
        '<rect x="0" y="0" w="40" h="10"/>'
        '<stroke/>'
        '</foreground>'
        '</shape>'
        '</shapes>',
      );
      expect(
        strokeTrans(includeHost).first,
        closeTo(0, 0.05),
        reason: 'first host inherit stroke keeps collectLine opaque',
      );
      expect(
        hasStrokeTrans(includeHost, 1),
        isTrue,
        reason: 'include-shape nested omitted strokealpha leftover-bakes '
            'LineColorTrans 1 so Draw does not paint the tile opaque',
      );

      final writer = VsdxWriter();
      final parser = DocumentParser();
      var doc = parser.parse(writer.emptyDocument());
      final laterId = doc.pages.first.nextFreeShapeId();
      doc = doc.replacePage(
        0,
        doc.pages.first.addShape(laterHost.copyWith(id: laterId)),
      );
      final leftover = parser
          .parse(
            writer.write(originalBytes: writer.emptyDocument(), edited: doc),
          )
          .pages
          .first
          .findShapeById(laterId)!;
      final paint = leftoverPaint(leftover);
      expect(
        paint.opaqueLine,
        greaterThan(0),
        reason: 'a second save keeps the first opaque rail Draw paints',
      );
      expect(
        paint.fadedFill,
        greaterThan(0),
        reason: 'LineColorTrans is not a token; leftover ribbons omitted '
            'strokealpha as FillForegndTrans 1 Draw paints',
      );
    },
  );

  test(
    'mxStencil mxXmlCanvas2D fillgradient omitted leftover bakes FillPattern 0 for LibreOffice',
    () {
      bool isGradient(VsdxFill fill) =>
          fill.pattern >= 25 && fill.pattern <= 40;

      bool hasFill(VsdxShape shape) {
        if (shape.fill.hasFill) return true;
        return shape.children.any(hasFill);
      }

      int fillCount(VsdxShape shape) {
        var n = 0;
        void walk(VsdxShape next) {
          if (next.fill.hasFill) n++;
          for (final child in next.children) {
            walk(child);
          }
        }

        walk(shape);
        return n;
      }

      bool hasGradientFill(VsdxShape shape) {
        if (isGradient(shape.fill)) return true;
        return shape.children.any(hasGradientFill);
      }

      bool hasStrokeOnly(VsdxShape shape) {
        if (shape.line.hasLine && !shape.fill.hasFill) return true;
        return shape.children.any(hasStrokeOnly);
      }

      final omitted = decodeDrawioMxStencilXml(
        '<shape name="O" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<fillgradient/>'
        '<rect x="0" y="0" w="40" h="10"/>'
        '<fillstroke/>'
        '</foreground>'
        '</shape>',
        id: 516,
      );
      expect(
        hasFill(omitted),
        isFalse,
        reason: 'omitted fillgradient color1 is NestedStencil '
            'isNoneColor(null) → setFillColor(null)/none; leftover '
            '_applyMxFill empty inherited FillForegnd so Draw painted '
            'palette fill (`tokens.txt` FillForegnd → svg:fill)',
      );
      expect(omitted.line.hasLine, isTrue);

      final omittedGradient = decodeDrawioMxStencilXml(
        '<shape name="G" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<gradient/>'
        '<rect x="0" y="0" w="40" h="10"/>'
        '<fillstroke/>'
        '</foreground>'
        '</shape>',
      );
      expect(
        hasFill(omittedGradient),
        isFalse,
        reason: 'omitted mxXmlCanvas2D <gradient/> c1 is the same none fill',
      );
      expect(omittedGradient.line.hasLine, isTrue);

      final keep = decodeDrawioMxStencilXml(
        '<shape name="K" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<fillgradient color1="#1565c0" color2="#bbdefb" direction="south"/>'
        '<rect x="0" y="0" w="40" h="10"/>'
        '<fillstroke/>'
        '<rect x="0" y="20" w="40" h="10"/>'
        '<fillstroke/>'
        '</foreground>'
        '</shape>',
      );
      expect(
        fillCount(keep),
        2,
        reason: 'without a later fillgradient node leftover keeps the '
            'previous FillPattern 28 on both rails',
      );
      expect(hasGradientFill(keep), isTrue);

      final laterHost = decodeDrawioMxStencilXml(
        '<shape name="L" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<fillgradient color1="#1565c0" color2="#bbdefb" direction="south"/>'
        '<rect x="0" y="0" w="40" h="10"/>'
        '<fillstroke/>'
        '<fillgradient/>'
        '<rect x="0" y="20" w="40" h="10"/>'
        '<fillstroke/>'
        '</foreground>'
        '</shape>',
      );
      expect(
        fillCount(laterHost),
        1,
        reason: 'later omitted fillgradient leftover-bakes a sibling so Draw '
            'does not inherit FillForegnd on the second rail',
      );
      expect(
        hasGradientFill(laterHost),
        isTrue,
        reason: 'first fillgradient south keeps FillPattern 28 Draw paints',
      );
      expect(
        hasStrokeOnly(laterHost),
        isTrue,
        reason: 'later omitted fillgradient fillstroke stays stroke-only',
      );

      final includeHost = decodeDrawioMxStencilXml(
        '<shapes name="mxgraph.test">'
        '<shape name="host" w="100" h="100" strokewidth="1">'
        '<foreground>'
        '<fillgradient color1="#1565c0" color2="#bbdefb" direction="south"/>'
        '<rect x="0" y="0" w="10" h="10"/>'
        '<fillstroke/>'
        '<include-shape name="mxgraph.test.tile" x="20" y="0" w="10" h="10"/>'
        '<rect x="0" y="80" w="10" h="10"/>'
        '<fillstroke/>'
        '</foreground>'
        '</shape>'
        '<shape name="tile" w="10" h="10" strokewidth="1">'
        '<foreground>'
        '<fillgradient/>'
        '<rect x="0" y="0" w="10" h="10"/>'
        '<fillstroke/>'
        '</foreground>'
        '</shape>'
        '</shapes>',
      );
      expect(
        fillCount(includeHost),
        1,
        reason: 'include-shape shares the canvas; nested omitted '
            'fillgradient turns FillPattern 0 for the tile and later '
            'host fillstroke',
      );
      expect(hasGradientFill(includeHost), isTrue);

      final writer = VsdxWriter();
      final parser = DocumentParser();
      var doc = parser.parse(writer.emptyDocument());
      final laterId = doc.pages.first.nextFreeShapeId();
      doc = doc.replacePage(
        0,
        doc.pages.first.addShape(laterHost.copyWith(id: laterId)),
      );
      final leftover = parser
          .parse(
            writer.write(originalBytes: writer.emptyDocument(), edited: doc),
          )
          .pages
          .first
          .findShapeById(laterId)!;
      expect(
        leftover.fill.hasFill ||
            leftover.children.any((child) => child.fill.hasFill),
        isTrue,
        reason: 'a second save keeps the first FillPattern 28 Draw paints',
      );
      expect(
        leftover.line.hasLine && !leftover.fill.hasFill ||
            leftover.children.any(
              (child) => child.line.hasLine && !child.fill.hasFill,
            ),
        isTrue,
        reason: 'a second save keeps the later stroke-only rail Draw paints',
      );
    },
  );

