      expect(descendants(leftover).where(isWhiteGear).length, 2);
      expect(
        descendants(leftover).any(
          (shape) =>
              !identical(shape, leftover) &&
              shape.fill.hasFill &&
              shape.fill.foreground == paletteBlue,
        ),
        isFalse,
      );
    },
  );

